body_md:
The basis functions $\{w_j\}_{j\ge 1}$ are the normalized eigenfunctions of $-d^2/dx^2$ on $\tilde{I}$ with homogeneous Dirichlet conditions,
\begin{equation} \label{eq:basis_func}
w_j(x) = \sqrt{\frac{2}{\tilde L}} \sin\bigl(\mu_j (x+\delta)\bigr), \qquad \mu_j = \frac{j\pi}{\tilde L},\quad \lambda_j = \mu_j^2, \quad \tilde L := L+2\delta .
\end{equation}

\label{def:collocation}
The solution $u_N = \sum_{j=1}^N c_j w_j$ is sought in the space $V_N = \operatorname{span}\{w_1, \dots, w_N\}$. With the equispaced nodes $x_m = (m-1)h$, $h = L/(N-1)$, $m = 1,\dots,N$, and the equation $\mathcal{L} u = f$ with Dirichlet data $u(0)=g_0$, $u(L)=g_L$, the coefficients solve the square system $\mathbf{A}\mathbf{c}=\mathbf{f}$,
\begin{equation}\label{eq:square_system}
(\mathbf{A})_{mj} = \begin{cases} w_j(x_m), & m \in \{1, N\},\\ (\mathcal{L} w_j)(x_m), & 2 \le m \le N-1,\end{cases}\qquad
(\mathbf{f})_m = \begin{cases} g_0,\ g_L, & m = 1,\ N,\\ f(x_m), & 2 \le m \le N-1. \end{cases}
\end{equation}

\label{def:lebesgue}
Let $X$ be an $n$-dimensional space of continuous functions on $\bar I$ and $\{y_m\}_{m=1}^n \subset \bar I$ nodes at which interpolation in $X$ is unisolvent. The interpolation operator $\mathcal{I}_{X}: C(\bar I) \to X$ maps $g$ to the element of $X$ agreeing with $g$ at the nodes, and its Lebesgue constant is
\begin{equation}
\Lambda(X) = \sup_{g \ne 0} \frac{\lVert\mathcal{I}_{X} g\rVert_{L^\infty(I)}}{\lVertg\rVert_{L^\infty(I)}} = \max_{x \in \bar I} \sum_{m=1}^n \lvert\ell_m(x)\rvert,
\end{equation}
with the Lagrange functions $\ell_m \in X$, $\ell_m(y_{m'}) = \delta_{mm'}$. We write $\Lambda_N := \Lambda(V_N)$ for the trial space with all $N$ nodes, and $\Lambda_N^\Psi := \Lambda(\Psi_N)$ for the test space of Definition~\ref{def:spaces} with the interior nodes.

\label{def:two_constants}
Denote by $\sigma_1 \ge \dots \ge \sigma_n$ the singular values of $\mathbf{B}_D$ and by $\mathbf{v}_1, \dots, \mathbf{v}_n$ its right singular vectors. For a threshold $t \ge 0$ let $\mathcal V_t := \operatorname{span}\{\mathbf{v}_i : \sigma_i \le t\}$ and $\mathcal V_t^{\perp} := \operatorname{span}\{\mathbf{v}_i : \sigma_i > t\}$, the spans of the singular vectors that the nodes see to size at most $t$ and to size above $t$, and define
\begin{equation}\label{eq:two_constants}
\gamma_t := \sup_{\mathbf{w} \in \mathcal V_t\setminus\{0\}} \frac{\lVert\Phi\mathbf{D}\mathbf{w}\rVert_{L^2(I)}}{\lVert\mathbf{w}\rVert_2}, \qquad
\Gamma_t := \sup_{\mathbf{w} \in \mathcal V_t^{\perp}\setminus\{0\}} \frac{\lVert\Phi\mathbf{D}\mathbf{w}\rVert_{L^2(I)}}{\lVert\mathbf{B}_D\mathbf{w}\rVert_2},
\end{equation}
with $\gamma_t := 0$ if $\mathcal V_t = \{0\}$ and $\Gamma_t := 0$ if $\mathcal V_t^\perp = \{0\}$.

\label{lem:chebyshev_variable}
Let $\theta = \pi(x+\delta)/\tilde L$ and $z = \cos\theta$. Then $w_j(x) = \sqrt{2/\tilde L}\,\sin\theta\, U_{j-1}(z)$ with $U_k$ the Chebyshev polynomial of the second kind, so that $V_N = \sqrt{2/\tilde L}\,\sin\theta\cdot\mathbb P_{N-1}(z)$. The extended domain $\tilde I$ corresponds to $z \in (-1,1)$ and the physical domain $I$ to $z \in (-c_0, c_0)$, $c_0 = \cos\theta_0$, $\theta_0 = \pi\delta/\tilde L$; we write $\omega := \pi - 2\theta_0 = \pi L/\tilde L \in (0,\pi)$. For $v = \sum_j c_j w_j = \sqrt{2/\tilde L}\,\sin\theta\, q(z)$, $q = \sum_j c_j U_{j-1}$,
\begin{equation}\label{eq:chebyshev_norms}
\lVertv\rVert_{L^2(\tilde I)}^2 = \sum_j c_j^2 = \frac{2}{\pi}\int_{-1}^{1} q(z)^2\sqrt{1-z^2}\,dz, \qquad
\lVertv\rVert_{L^2(I)}^2 = \frac{2}{\pi}\int_{-c_0}^{c_0} q(z)^2\sqrt{1-z^2}\,dz .
\end{equation}
The equispaced nodes $x_m$ correspond to $\theta_m = \theta_0 + (m-1)\omega/(N-1)$ and $z_m = \cos\theta_m$; their normalized counting measures converge weakly to
\begin{equation}\label{eq:node_measure}
d\mu_\omega(z) = \frac{dz}{\omega\sqrt{1-z^2}}\quad\text{on } [-c_0, c_0],
\end{equation}
the arcsine density of $[-1,1]$ restricted to $[-c_0,c_0]$ and renormalized by the factor $\pi/\omega = \tilde L/L$.

\label{thm:representation}
Let Assumption~\ref{ass:unisolvence} hold, let $f \in C(\bar I)$, and let $u_N \in V_N$ solve \eqref{eq:square_system} with $g_0 = g_L = 0$. Then $u_N \in \Phi_N$ and
\begin{equation}\label{eq:representation}
u_N = \mathcal{L}^{-1} \mathcal{P}_N f, \qquad\text{i.e.}\qquad u_N(x) = \int_0^L G(x,y)\,(\mathcal{P}_N f)(y)\,dy \quad (x \in \bar I).
\end{equation}

\label{cor:error}
With $u = \mathcal{L}^{-1}f$,
\begin{equation}\label{eq:error_bound}
u - u_N = \mathcal{L}^{-1}(f - \mathcal{P}_N f), \qquad
\lVertu - u_N\rVert_{L^\infty(I)} \le \lVert\mathcal{L}^{-1}\rVert_\infty\,\bigl(1 + \Lambda_N^\Psi\bigr)\, \operatorname{dist}_\infty(f, \Psi_N),
\end{equation}
where $\operatorname{dist}_\infty(f,\Psi_N) := \inf_{\psi\in\Psi_N}\lVertf - \psi\rVert_{L^\infty(I)}$.

\label{thm:rates}
Let $\Lambda_N = \Lambda(V_N)$ be the trial-space Lebesgue constant at the $N$ equispaced nodes. Then
\begin{equation}\label{eq:rates}
\begin{aligned}
\lim_{N\to\infty}\frac{\log\Lambda_N}{N} &= \kappa_\Lambda(\omega) := U_\omega(0) - U_\omega(c_0) = \frac{\mathrm{Cl}_2(\omega) - \tfrac12\mathrm{Cl}_2(2\omega)}{\omega}, \\
\lim_{N\to\infty}\frac{\log\bigl(1/\sigma_{\min}(\mathbf{W}_N)\bigr)}{N} &= \kappa_\sigma(\omega) := U_\omega(0) - U_\omega(1) = \frac{\mathrm{Cl}_2(\omega) + \mathrm{Cl}_2(\pi-\omega)}{\omega}.
\end{aligned}
\end{equation}

\label{cor:exponent}
Let $x_1, \dots, x_N$ be the equispaced nodes of Definition~\ref{def:collocation}. For $v \in V_N\setminus\{0\}$ let $t(v) := \bigl(\sum_{m=1}^N v(x_m)^2\bigr)^{1/2}/\lVertv\rVert_{L^2(\tilde I)}$ be its nodal size at these nodes and $g(v) := \lVertv\rVert_{L^2(I)}/\lVertv\rVert_{L^2(\tilde I)}$ its leakage, and let $\ell^\ast \in V_N$ be the Lagrange function of $V_N$ at these nodes for a node nearest to the centre of $I$: $\ell^\ast(x_m) = \delta_{mm^\ast}$ for $1 \le m \le N$, where $m^\ast$ minimizes $|x_m - L/2|$ (either of the two such indices when $N$ is even); it exists by Lemma~\ref{lem:lebesgue_condition_link}. Then $N^{-1}\log t(\ell^\ast) = -\kappa_\sigma(\omega) + O(\log N/N)$, the rate of $\sigma_{\min}(\mathbf{W}_N)$ in Theorem~\ref{thm:rates}, and
\begin{equation}\label{eq:exponent}
\lim_{N\to\infty}\frac{\log g(\ell^\ast)}{\log t(\ell^\ast)} = a(\omega) := 1 - \frac{\kappa_\Lambda(\omega)}{\kappa_\sigma(\omega)} = \frac{\tfrac12\mathrm{Cl}_2(2\omega) + \mathrm{Cl}_2(\pi-\omega)}{\mathrm{Cl}_2(\omega) + \mathrm{Cl}_2(\pi-\omega)} .
\end{equation}

\label{thm:two_constant}
Let $u = \mathcal{L}^{-1}f$, let $\hat{\mathbf{y}} \in \mathbb R^{n}$ be arbitrary, $\hat u_N := \Phi\mathbf{D}\hat{\mathbf{y}}$, and let $\hat\rho := \lVert\mathbf{f} - \mathbf{B}_D\hat{\mathbf{y}}\rVert_2$ be its nodal residual, $\mathbf{f} = (f(x_m))_m$. Then for every $t \ge 0$ and every $\mathbf{y} \in \mathbb R^n$ with $u_{\mathbf{y}} := \Phi\mathbf{D}\mathbf{y}$ and $\mathbf{d} := \hat{\mathbf{y}} - \mathbf{y}$,
\begin{equation}\label{eq:two_constant_bound}
\lVertu - \hat u_N\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + \Gamma_t\bigl(\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2 + \hat\rho + t\lVert\mathbf{d}\rVert_2\bigr) + \gamma_t\lVert\mathbf{d}\rVert_2 .
\end{equation}

\label{cor:regimes_two_constant}\leavevmode
\begin{enumerate}
    \item[(i)] Let $M = n$ and let Assumption~\ref{ass:unisolvence} hold. For the interpolatory solution $u_N$ of Theorem~\ref{thm:representation}, $\hat\rho = 0$, and with $t = 0$ the bound reads $\lVertu - u_N\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + \Gamma_0\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2$, where $\Gamma_0 \ge \lVert\Phi\mathbf{D}\mathbf{v}_n\rVert_{L^2(I)}/\sigma_n$.
    \item[(ii)] For the regularized solution \eqref{eq:tsvd} with threshold $\varepsilon$, $\hat\rho \le \lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2 + \varepsilon\lVert\mathbf{y}\rVert_2$ and $\lVert\mathbf{d}\rVert_2 \le 2\lVert\mathbf{y}\rVert_2 + \varepsilon^{-1}\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2$, and with $t = \varepsilon$
    \[
    \lVertu - u_N^\varepsilon\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + (3\Gamma_\varepsilon + 2\gamma_\varepsilon\varepsilon^{-1})\bigl(\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2 + \varepsilon\lVert\mathbf{y}\rVert_2\bigr).
    \]
    \item[(iii)] Let $M = n$, and let $\hat{\mathbf{y}}$ be computed by a solver with backward error $\eta > 0$, i.e.\ suppose that there is a matrix $\mathbf{E} \in \mathbb R^{n\times n}$ with $(\mathbf{B}_D + \mathbf{E})\hat{\mathbf{y}} = \mathbf{f}$ and $\lVert\mathbf{E}\rVert_2 \le \eta$. Then $\hat\rho \le \eta\lVert\hat{\mathbf{y}}\rVert_2$; if in addition this $\mathbf{E}$ satisfies $\sigma_{\min}(\mathbf{B}_D + \mathbf{E}) \ge \eta/K$ for some $K > 0$, then $\lVert\mathbf{d}\rVert_2 \le K\bigl(\lVert\mathbf{y}\rVert_2 + \eta^{-1}\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2\bigr)$, and with $t = \eta$
    \begin{equation}\label{eq:lu_bound}
    \lVertu - \hat u_N\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + \bigl[(1 + 2K)\Gamma_\eta + K\gamma_\eta\eta^{-1}\bigr]\bigl(\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2 + \eta\lVert\mathbf{y}\rVert_2\bigr).
    \end{equation}
\end{enumerate}

\label{prop:apriori}
There are $N_0$ and $C_\Phi > 0$, depending only on $\delta$, $L$ and $k$, such that for all $N \ge N_0$ and all $\mathbf{w} \in \mathbb R^n$, $\lVert\Phi\mathbf{D}\mathbf{w}\rVert_{L^2(\tilde I)} \le C_\Phi\lVert\mathbf{w}\rVert_2$. Consequently $\gamma_t \le C_\Phi$ for every $t \ge 0$, $\Gamma_t \le C_\Phi/t$ for every $t > 0$, and under the hypotheses of Corollary~\ref{cor:regimes_two_constant}(iii)
\begin{equation}\label{eq:apriori_lu}
\lVertu - \hat u_N\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + (1 + 3K)\,C_\Phi\bigl(\lVert\mathbf{y}\rVert_2 + \eta^{-1}\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2\bigr).
\end{equation}

\label{prop:classical}
Let Assumption~\ref{ass:unisolvence} hold, and let $\Lambda^\Psi_{N,2} := \max_m\lVert\ell_m^\Psi\rVert_{L^2(I)} \le \sqrt L\,\Lambda_N^\Psi$.
\begin{enumerate}
    \item[(i)] For every $t \ge 0$,
    \begin{equation}\label{eq:classical}
    \gamma_t \le \frac{L^2}{\pi^2}\sqrt n\,\Lambda^\Psi_{N,2}\,t, \qquad \Gamma_t \le \frac{L^2}{\pi^2}\sqrt n\,\Lambda^\Psi_{N,2},
    \end{equation}
    and under the hypotheses of Corollary~\ref{cor:regimes_two_constant}(iii)
    \begin{equation}\label{eq:classical_lu}
    \lVertu - \hat u_N\rVert_{L^2(I)} \le \lVertu - u_{\mathbf{y}}\rVert_{L^2(I)} + (1 + 3K)\,\frac{L^2}{\pi^2}\sqrt n\,\Lambda^\Psi_{N,2}\bigl(\lVert\mathbf{f} - \mathbf{B}_D\mathbf{y}\rVert_2 + \eta\lVert\mathbf{y}\rVert_2\bigr).
    \end{equation}
\end{enumerate}
If $\mathcal{L} = \mathcal{L}_P$, there are $N_0$ and $C$, depending only on $\delta$ and $L$, such that for all $N \ge N_0$ moreover:
\begin{enumerate}
    \item[(ii)] $\lVert\ell_m^\Psi\rVert_{L^\infty(I)} \le N^C\exp\bigl(N[U_\omega(z_m) - U_\omega(c_0)]\bigr)$ for $2 \le m \le N-1$, with $z_m = \cos\theta_m$ as in Lemma~\ref{lem:chebyshev_variable};
    \item[(iii)] $\Lambda_N^\Psi \le N^Ce^{N\kappa_\Lambda(\omega)}$ and $\Lambda^\Psi_{N,2} \le N^Ce^{N\kappa_\Lambda(\omega)}$;
    \item[(iv)] $\gamma_t \le N^Ce^{N\kappa_\Lambda(\omega)}\,t$ and $\Gamma_t \le N^Ce^{N\kappa_\Lambda(\omega)}$ for all $t \ge 0$; in particular, at $t = e^{-N\kappa_\sigma(\omega)}$,
    \begin{equation}\label{eq:endpoint_law}
    \gamma_t \le N^C\,t^{\,a(\omega)}, \qquad \Gamma_t \le N^C\,t^{\,a(\omega)-1}.
    \end{equation}
\end{enumerate}

\label{thm:competitor}
Let $1 < \rho \le \rho^\ast$, and let $f$ extend analytically to an open simply connected set $\mathcal D \supset \bar\Omega_\rho$. Then $u = \mathcal{L}^{-1}f$ extends analytically to $\mathcal D$, and there is a constant $C$, depending on $f$, $\rho$, $\delta$, $L$ and $k$, such that for every $N \ge 3$ and every integer ${2 \le p \le N-1}$ there is $v_p \in \Phi_N$ with
\begin{enumerate}
    \item[(i)] $\lVertf - \mathcal{L} v_p\rVert_{L^\infty(I)} \le C p^{9/2}\rho^{-p}$ and $\lVertu - v_p\rVert_{L^\infty(I)} \le C p^{1/2}\rho^{-p}$;
    \item[(ii)] $\lVertv_p''\rVert_{L^2(\tilde I)} + k\lVertv_p'\rVert_{L^2(\tilde I)} \le C p^{11/2}(\rho^\ast/\rho)^p$;
    \item[(iii)] for $N \ge N_0$, with $N_0$ and $C_B$ of Lemma~\ref{lem:column_norms}, the coefficient vector $\mathbf{y}_p$ with $v_p = \Phi\mathbf{D}\mathbf{y}_p$ satisfies $\lVert\mathbf{y}_p\rVert_2 \le C_BC\sqrt N\,p^{11/2}(\rho^\ast/\rho)^p$.
\end{enumerate}

\label{cor:unconditional}
Assume the hypotheses of Theorem~\ref{thm:competitor} and of Corollary~\ref{cor:regimes_two_constant}(iii), and let $N \ge N_0$ of Lemma~\ref{lem:column_norms}; $C$ denotes constants depending on $f$, $\rho$, $\delta$, $L$ and $k$.
\begin{enumerate}
    \item[(i)] For every integer ${2 \le p \le N-1}$,
    \begin{equation}\label{eq:unconditional}
\lVertu - \hat u_N\rVert_{L^2(I)} \le C\sqrt N\,p^{11/2}\Bigl\{\rho^{-p} + \bigl[(1+2K)\Gamma_\eta + K\gamma_\eta\eta^{-1}\bigr]\bigl(\rho^{-p} + \eta\,(\rho^\ast/\rho)^p\bigr)\Bigr\}.
\end{equation}
    \item[(ii)] With $a' := \log\rho/\log\rho^\ast \in (0,1]$, if $\eta \le \rho^{\ast\,-2}$ and $N \ge 2 + \log(1/\eta)/\log\rho^\ast$, then
    \begin{equation}\label{eq:unconditional_floor}
\lVertu - \hat u_N\rVert_{L^2(I)} \le C\sqrt N\,\bigl(1 + \log(1/\eta)\bigr)^{11/2}\bigl(1 + (1+2K)\Gamma_\eta + K\gamma_\eta\eta^{-1}\bigr)\,\eta^{a'}.
\end{equation}
    \item[(iii)] If $\rho = \rho^\ast$, then under the conditions of (ii)
    \[
    \lVertu - \hat u_N\rVert_{L^2(I)} \le C\sqrt N\,(1 + \log(1/\eta))^{11/2}\bigl(\eta + (1+3K)C_\Phi\bigr),
    \]
    a bound independent of the conditioning of the system.
\end{enumerate}

\label{prop:equilibrium}
For every $\tau \ge 0$ the functional $J_\tau$ has a unique minimizer $\lambda_\tau$ on $\mathscr A_\omega$. It is invariant under $\vartheta\mapsto\pi-\vartheta$, its envelope $E_\tau := E_{\lambda_\tau}$ is continuous on $[0,\pi]$, and with $E_\tau^\ast := \max_{[0,\pi]}E_\tau$:
\begin{enumerate}
    \item[(i)] $E_\tau^\ast - \tau \le E_\tau \le E_\tau^\ast$ on $[0,\pi]$;
    \item[(ii)] $E_\tau = E_\tau^\ast$ on the support of $\lambda_\tau|_{\Theta_E}$, and $E_\tau = E_\tau^\ast - \tau$ on the support of $(\omega^{-1}d\theta - \lambda_\tau)|_{\Theta_I}$, the set of points of the physical arc near which $\lambda_\tau$ does not coincide with the node density;
    \item[(iii)] if $\tau < \kappa_\sigma$, then $\lambda_\tau(\Theta_E) > 0$ and there is a unique $\theta_\tau \in [\theta_0,\pi/2)$ such that $\lambda_\tau = \omega^{-1}d\theta$ on $[\theta_0,\theta_\tau]\cup[\pi-\theta_\tau,\pi-\theta_0]$ and $E_\tau = E_\tau^\ast - \tau$ on $[\theta_\tau,\pi-\theta_\tau]$; moreover $\max_{\Theta_I}E_\tau = E_\tau(\theta_0)$;
    \item[(iv)] if $\tau \ge \kappa_\sigma$, then $\lambda_\tau = \mu_\omega$.
\end{enumerate}

\label{thm:tail_law}
Let $\mathcal{L} = \mathcal{L}_P$. For every $\tau \in (0,\kappa_\sigma)$,
\begin{equation}\label{eq:tail_limit}
\lim_{N\to\infty}\frac1N\log\max\{\gamma_{t_N},\ t_N\Gamma_{t_N}\} = r_\omega(\tau), \qquad t_N = e^{-N\tau}.
\end{equation}

\label{prop:tail_properties}
The function $r_\omega$ is nonincreasing on $(0,\kappa_\sigma)$, satisfies $|r_\omega(\tau) - r_\omega(\tau')| \le |\tau - \tau'|$, and
\begin{equation}\label{eq:tail_law_bounds}
-\tau \le r_\omega(\tau) \le \min\{0,\ \kappa_\Lambda - \tau\}, \qquad r_\omega(\tau) > \kappa_\Lambda - \kappa_\sigma ;
\end{equation}
in particular $r_\omega(\tau) \to 0$ as $\tau \to 0$ and $r_\omega(\tau) \to \kappa_\Lambda - \kappa_\sigma = -a(\omega)\kappa_\sigma$ as $\tau \to \kappa_\sigma$.

\label{thm:tail_duality}
For $\omega \in (0,\pi)$ and $0 < \bar\tau < 1$ let $\bar r_\omega(\bar\tau) := r_\omega(\bar\tau\kappa_\sigma(\omega))/\kappa_\sigma(\omega)$ be the tail law in units of $\kappa_\sigma(\omega)$. Then
\begin{equation}\label{eq:tail_duality}
\bar r_\omega(\bar\tau) + \bar r_{\pi-\omega}(\bar\tau) = -\bar\tau \qquad (0 < \bar\tau < 1).
\end{equation}

\label{thm:initial_slope}
For every $\omega \in (0,\pi)$ there are $C$ and $\tau_0 \in (0,\kappa_\sigma)$ such that
\begin{equation}\label{eq:initial_slope}
\bigl|r_\omega(\tau) + s(\omega)\,\tau\bigr| \le C\tau^{3/2} \qquad (0 < \tau \le \tau_0).
\end{equation}

\label{cor:critical}
\leavevmode
\begin{enumerate}
    \item[(i)] If $\delta < L/2$, then $r_\omega(\tau) > -a(\omega)\tau$ for all sufficiently small $\tau > 0$, and for $\mathcal{L} = \mathcal{L}_P$ there are no $N_1$ and $C$ such that $\gamma_t \le Ct^{\,a(\omega)}$ for all $N \ge N_1$ and all $t > 0$; in particular the sharp power law \eqref{eq:sharp_law} fails.
    \item[(ii)] If $\delta > L/2$, then $r_\omega(\tau) < -a(\omega)\tau$ for all sufficiently small $\tau > 0$.
\end{enumerate}

\label{def:configuration}
Let $0 < \xi \le \theta_0/2$. A \emph{configuration} $\mathcal C$ consists of a layer parameter $\theta_s \in (\theta_0, \pi/2)$ and finitely many arcs $A_k = [\alpha_k, \beta_k]$, $1 \le k \le Q$, with densities $\rho_k > 0$, such that
\begin{enumerate}
    \item[(i)] $\xi \le \alpha_k < \beta_k \le \pi/2$, the arcs have pairwise disjoint interiors, and each arc lies either in $[\xi, \theta_0)$ (an \emph{extension arc}, so that $\beta_k < \theta_0$) or in $[\theta_s, \pi/2]$ (a \emph{centre arc});
    \item[(ii)] with $A_k^\ast := A_k \cup (\pi - A_k)$, of length $|A_k^\ast| = 2(\beta_k - \alpha_k)$ if $\beta_k < \pi/2$ and $|A_k^\ast| = \pi - 2\alpha_k$ if $\beta_k = \pi/2$, the total mass $m(\mathcal C) := 2(\theta_s - \theta_0)/\omega + \sum_{k=1}^Q\rho_k|A_k^\ast|$ is less than one.
\end{enumerate}
With $S := [\theta_0, \theta_s]$ (the \emph{layer}) and $S^\ast := S \cup (\pi - S)$, the \emph{envelope} of $\mathcal C$ is
\begin{equation}\label{eq:envelope}
E(\vartheta) := \frac1\omega\int_{S^\ast}\log|\cos\vartheta - \cos\varphi|\,d\varphi + \sum_{k=1}^Q\rho_k\int_{A_k^\ast}\log|\cos\vartheta - \cos\varphi|\,d\varphi, \qquad \vartheta \in [0,\pi],
\end{equation}
and we put
\begin{gather*}
E_{\max} := \max_{[0,\pi]}E, \qquad E_c := \max_{[\theta_s,\ \pi-\theta_s]}E, \\
\ell(\mathcal C) := E(\theta_0) - E_{\max} \le 0, \qquad \tau(\mathcal C) := E_{\max} - E_c \ge 0 .
\end{gather*}

\label{thm:tail_lower}
Let $\mathcal{L} = \mathcal{L}_P$, let $\mathcal C$ be a configuration with $\ell := \ell(\mathcal C)$, $\tau := \tau(\mathcal C)$, and assume $\ell > -(\kappa_\sigma - \kappa_\Lambda)$. Then there are $N_0$ and $C$, depending only on $\delta$, $L$ and $\mathcal C$, and, for every $N \ge N_0$, a vector $\mathbf{w}_N \in \mathbb R^n\setminus\{0\}$ such that for all $s \in [0,1]$
\begin{equation}\label{eq:tail_quotient}
\frac1N\log\frac{\lVert\Phi\mathbf{D}\mathbf{w}_N\rVert_{L^2(I)}}{\lVert\mathbf{B}_D\mathbf{w}_N\rVert_2^{\,s}\,\lVert\mathbf{w}_N\rVert_2^{\,1-s}} \ \ge\ \ell + s\tau - C\,\frac{\log N}{N},
\end{equation}
where $\lVert\mathbf{B}_D\mathbf{w}_N\rVert_2 > 0$ by Proposition~\ref{prop:unisolvence_poisson}.

\label{def:interp_configuration}
Let $0 < \xi \le \theta_0/2$. An \emph{interpolation configuration} $\mathcal S$ consists of finitely many pairwise disjoint arcs $A_k = [\alpha_k,\beta_k]$, $\alpha_k < \beta_k$, with densities $\rho_k > 0$, $1 \le k \le Q$, such that
\begin{enumerate}
    \item[(i)] the \emph{node arcs} $A_k$, $1 \le k \le Q_1$, with $Q_1 \ge 1$, lie in $[\theta_0, \pi-\theta_0]$, and each carries a modulus $q_k \in \mathbb N$ and a nonempty set of residues $R_k \subset \{0, 1, \dots, q_k-1\}$, with $\rho_k := |R_k|/(q_k\omega) \le 1/\omega$;
    \item[(ii)] the \emph{virtual arcs} $A_k$, $Q_1 < k \le Q$, with $Q > Q_1$, lie in $[\xi, \pi-\xi]$;
    \item[(iii)] the total mass $\sum_{k=1}^Q\rho_k(\beta_k - \alpha_k)$ equals one.
\end{enumerate}
Its \emph{envelope} is
\begin{equation}\label{eq:interp_envelope}
E(\vartheta) := \sum_{k=1}^Q\rho_k\int_{A_k}\log|\cos\vartheta - \cos\varphi|\,d\varphi, \qquad \vartheta \in [0,\pi],
\end{equation}
a continuous function (Lemma~\ref{lem:E_modulus}), and with $E_I := \max_{[\theta_0,\pi-\theta_0]}E$, $E_1$ the minimum of $E$ over the node arcs and $E_2$ its minimum over the virtual arcs, we put
\begin{gather*}
A_1(\mathcal S) := E_I - E_1 \ge 0, \qquad A_2(\mathcal S) := E_I - E_2, \\
\Phi(\mathcal S,\tau) := \max\{A_1(\mathcal S) - \tau,\ A_2(\mathcal S)\} \qquad (\tau \ge 0).
\end{gather*}

\label{thm:dual}
Let $\mathcal{L} = \mathcal{L}_P$ and let $\mathcal S$ be an interpolation configuration. There are $N_0$ and $C$, depending only on $\delta$, $L$ and $\mathcal S$, such that for all $N \ge N_0$ and all $t \ge 0$
\begin{equation}\label{eq:dual_bound}
\max\{\gamma_t,\ t\Gamma_t\} \le N^C\bigl(t\,e^{NA_1(\mathcal S)} + e^{NA_2(\mathcal S)}\bigr);
\end{equation}
consequently, for every $\tau \ge 0$ and $t_N := e^{-N\tau}$,
\begin{equation}\label{eq:dual_rate}
\frac1N\log\max\{\gamma_{t_N},\ t_N\Gamma_{t_N}\} \le \Phi(\mathcal S,\tau) + C\,\frac{\log N}{N}.
\end{equation}

\label{cor:sharpness}
For every $\tau \in (0,\kappa_\sigma)$,
\begin{equation}\label{eq:sharpness}
r_\omega(\tau) = \sup_{\mathcal C}\,\ell(\mathcal C) = \inf_{\mathcal S}\,\Phi(\mathcal S,\tau),
\end{equation}
the supremum being taken over the configurations $\mathcal C$ with $\tau(\mathcal C) \ge \tau$ and $\ell(\mathcal C) > -(\kappa_\sigma - \kappa_\Lambda)$ and the infimum over the interpolation configurations $\mathcal S$.

\label{lem:unisolvence}
Let $\mathcal{L} = \mathcal{L}_P = -d^2/dx^2$, let $\tilde\mathcal{L}_P^{-1}: V_N \to V_N$ be its inverse on $V_N$, $\tilde\mathcal{L}_P^{-1}w_j = \lambda_j^{-1}w_j$, and let $\tilde G(x,y) = (x+\delta)(L+\delta-y)/\tilde L$ for $x \le y$, $\tilde G(x,y) = \tilde G(y,x)$ for $x > y$, be the Green's function of $\mathcal{L}_P$ with Dirichlet conditions on $\tilde I$, so that $(\tilde\mathcal{L}_P^{-1}\psi)(x) = \int_{\tilde I}\tilde G(x,y)\psi(y)\,dy$ for $\psi \in V_N$. In the notation of Section~\ref{sec:variable} ($\theta = \pi(x+\delta)/\tilde L$, $z = \cos\theta$, $z_m = \cos\theta_m$) put $w_N^\circ(z) := \prod_{m=2}^{N-1}(z - z_m)$, $\psi_0 := \sin\theta\; w_N^\circ(z)$ and $\psi_1 := \sin\theta\; z\,w_N^\circ(z)$. Then Assumption~\ref{ass:unisolvence} holds if and only if
\begin{equation}\label{eq:unisolvence_criterion}
\int_{-\delta}^{L+\delta}\tilde G(0,y)\,\psi_0(y)\,dy \ne 0 \quad\text{and}\quad \int_{-\delta}^{L+\delta}\tilde G(0,y)\,\psi_1(y)\,dy \ne 0 .
\end{equation}

\label{lem:phase}
For $v = \sum_{j=1}^N c_j w_j \in V_N$ and constant $k \ge 0$,
\begin{equation}\label{eq:phase}
\mathcal{L}_{CD} v = \sqrt{\tfrac{2}{\tilde L}} \sum_{j=1}^N c_j\, \mu_j \sqrt{\mu_j^2 + k^2}\; \sin\bigl(\mu_j(x+\delta) + \vartheta_j\bigr), \qquad \vartheta_j = \arctan\frac{k}{\mu_j} \in \Bigl[0, \frac{k \tilde L}{j\pi}\Bigr].
\end{equation}

\label{rem:divergence}
The exact solution of the collocation system depends on $f$ only through its nodal values, which a computation knows only to finite precision. Let Assumption~\ref{ass:unisolvence} hold, and let $\tilde u_N$ be the exact solution of \eqref{eq:square_system} with $g_0 = g_L = 0$ and interior data $f(x_m) + e_m$, $2 \le m \le N-1$. Theorem~\ref{thm:representation}, applied to these nodal data as noted after its proof, gives $\tilde u_N = u_N + \mathcal{L}^{-1}\sum_{m=2}^{N-1}e_m\ell_m^\Psi$, and Corollary~\ref{cor:error} gives
\begin{equation}\label{eq:perturbed_data}
\lVertu - \tilde u_N\rVert_{L^\infty(I)} \le \lVert\mathcal{L}^{-1}\rVert_\infty\Bigl[\bigl(1 + \Lambda_N^\Psi\bigr)\operatorname{dist}_\infty(f,\Psi_N) + \Lambda_N^\Psi\max_{m}|e_m|\Bigr].
\end{equation}
The first term bounds the error for exact data and the second the effect of the data errors. In $L^2(I)$ the amplification factor is exactly the constant $\Gamma_0$ of Definition~\ref{def:two_constants} with $M = n$: for $\mathbf{e} := (e_m)_{m=2}^{N-1} \in \mathbb R^n$, $\mathcal{L}^{-1}\sum_m e_m\ell_m^\Psi = \Phi\mathbf{D}\mathbf{B}_D^{-1}\mathbf{e}$, so that $\sup_{\mathbf{e}\ne0}\lVert\mathcal{L}^{-1}\sum_m e_m\ell_m^\Psi\rVert_{L^2(I)}/\lVert\mathbf{e}\rVert_2 = \Gamma_0$, and for the Poisson operator $\Gamma_0$ grows with the exponential rate $\kappa_\Lambda$ (Corollary~\ref{cor:lebesgue_rate}). For data rounded to a fixed precision the second term eventually dominates the bound, and beyond a threshold in $N$ the exact solution is observed to diverge (Section~\ref{sec:num_1d}).

\label{cor:greens}
Let Assumption~\ref{ass:unisolvence} hold, and let $\mathbf{G}_N := \mathbf{W}_N \mathbf{A}^{-1}$, with the synthesis matrix $\mathbf{W}_N$ of Section~\ref{sec:res_rates}, so that $\mathbf{u} = \mathbf{G}_N \mathbf{f}$ maps nodal data to nodal values of $u_N$. For $1 \le i \le N$ and $2 \le m \le N-1$,
\begin{equation}\label{eq:GN_entries}
\begin{aligned}
(\mathbf{G}_N)_{im} &= \int_0^L G(x_i, y)\, \ell_m^\Psi(y)\, dy, \\
|(\mathbf{G}_N)_{im}| &\le \lVertG(x_i,\cdot)\rVert_{L^\infty}\, \lVert\ell_m^\Psi\rVert_{L^1(I)}, \qquad
\sum_{m} |(\mathbf{G}_N)_{im}| \le \lVert\mathcal{L}^{-1}\rVert_\infty\, \Lambda_N^\Psi .
\end{aligned}
\end{equation}

\label{lem:clausen}
For $z = \cos\theta$, $0 \le \theta \le \pi$,
\begin{equation}\label{eq:U_closed}
U_\omega(\cos\theta) = \log 2 + \frac{1}{\omega}\Bigl[\mathrm{Cl}_2(\theta-\theta_0) - \mathrm{Cl}_2(\theta+\theta_0) + \mathrm{Cl}_2(\pi-\theta-\theta_0) - \mathrm{Cl}_2(\pi-\theta+\theta_0)\Bigr].
\end{equation}
In particular
\begin{equation}\label{eq:U_values}
U_\omega(1) = \log 2 - \frac{\mathrm{Cl}_2(\pi-\omega)}{\omega}, \quad
U_\omega(c_0) = \log 2 + \frac{\mathrm{Cl}_2(2\omega)}{2\omega}, \quad
U_\omega(0) = \log 2 + \frac{\mathrm{Cl}_2(\omega)}{\omega},
\end{equation}
and $U_\omega(\cos\theta)$ is increasing on $[0,\pi/2]$ and invariant under $\theta \mapsto \pi-\theta$, so that $U_\omega$ is even in $z$ and decreasing in $|z|$: its maximum is $U_\omega(0)$, its minimum on the physical interval is $U_\omega(\pm c_0)$, and its minimum on $[-1,1]$ is $U_\omega(\pm 1)$.

\label{prop:lagrange_norms}
For $N \ge N_0$, with $N_0$ depending only on $\theta_0$, and uniformly in $1 \le m \le N$, with implied constants depending only on $\delta$ and $L$,
\begin{equation}\label{eq:lagrange_norms}
\begin{aligned}
N^{-1}\log\lVert\ell_m^V\rVert_{L^2(\tilde I)} &= U_\omega(z_m) - U_\omega(1) + O(\log N/N), \\
N^{-1}\log\lVert\ell_m^V\rVert_{L^2(I)} &= U_\omega(z_m) - U_\omega(c_0) + O(\log N/N), \\
N^{-1}\log\lVert\ell_m^V\rVert_{L^\infty(I)} &= U_\omega(z_m) - U_\omega(c_0) + O(\log N/N).
\end{aligned}
\end{equation}

Let $m^\ast$ be an index with $|\theta_{m^\ast} - \pi/2| \le \Delta/2$, so that $|U_\omega(z_{m^\ast}) - U_\omega(0)| \le C\Delta\log(1/\Delta)$ by \eqref{eq:U_modulus}; since $U_\omega(z_m) \le U_\omega(0)$ for every $m$ by Lemma~\ref{lem:clausen}, Proposition~\ref{prop:lagrange_norms} gives
\begin{gather*}
N^{-1}\log\max_m\lVert\ell_m^V\rVert_{L^\infty(I)} = U_\omega(0) - U_\omega(c_0) + O(\log N/N), \\
N^{-1}\log\max_m\lVert\ell_m^V\rVert_{L^2(\tilde I)} = U_\omega(0) - U_\omega(1) + O(\log N/N).
\end{gather*}
For the first limit in \eqref{eq:rates}, $\max_m\lVert\ell_m^V\rVert_{L^\infty(I)} \le \Lambda_N \le N\max_m\lVert\ell_m^V\rVert_{L^\infty(I)}$ by the definition of the Lebesgue constant. For the second, $\mathbf{W}_N$ maps coefficient vectors to nodal values, so the $m$-th column of $\mathbf{W}_N^{-1}$ is the coefficient vector of $\ell_m^V$, whose Euclidean norm is $\lVert\ell_m^V\rVert_{L^2(\tilde I)}$ by \eqref{eq:chebyshev_norms}; hence $\max_m\lVert\ell_m^V\rVert_{L^2(\tilde I)} \le \lVert\mathbf{W}_N^{-1}\rVert_2 \le \lVert\mathbf{W}_N^{-1}\rVert_F \le \sqrt N\max_m\lVert\ell_m^V\rVert_{L^2(\tilde I)}$, and $\sigma_{\min}(\mathbf{W}_N) = 1/\lVert\mathbf{W}_N^{-1}\rVert_2$. The closed forms in \eqref{eq:rates} are \eqref{eq:U_values}.

\label{prop:backward}
Let Assumption~\ref{ass:unisolvence} hold, let $\mathbf{B}$ be the square interior collocation matrix of the recombined basis ($M = n$), let $\hat{\mathbf{c}} \in \mathbb R^n$ satisfy $(\mathbf{B} + \mathbf{E})\hat{\mathbf{c}} = \mathbf{f}$ for some perturbation $\mathbf{E}$, $\mathbf{f} = (f(x_m))_{m=2}^{N-1}$, and put $\hat u_N := \sum_j \hat c_j\varphi_j \in \Phi_N$. Then $\hat u_N$ is the exact interpolatory collocation solution for the nodal data $\mathbf{f} - \mathbf{E}\hat{\mathbf{c}}$:
\begin{equation}\label{eq:backward}
\hat u_N = \mathcal{L}^{-1}\mathcal{P}_N\bigl(\mathbf{f} - \mathbf{E}\hat{\mathbf{c}}\bigr), \qquad u - \hat u_N = \mathcal{L}^{-1}\bigl(f - \mathcal{P}_N(\mathbf{f} - \mathbf{E}\hat{\mathbf{c}})\bigr).
\end{equation}

