\label{lem:cheb}
For $f \in L^2(0,\pi)$ and every $\vartheta \in [0,\pi]$,
\begin{equation}\label{eq:cheb}
E_f(\vartheta) = -\hat f_0\log 2 - \sum_{k\ge1}\frac2k\,\hat f_k\cos k\vartheta, \qquad J_0(f) = \hat f_0^{\,2}\log 2 + \sum_{k\ge1}\frac2k\,\hat f_k^{\,2},
\end{equation}
the first series converging absolutely and uniformly. Consequently $E_f$ is continuous, $f$ is determined by $E_f$, and $J_0(f) > 0$ if $\hat f_0 = 0$ and $f \ne 0$.

\emph{Existence, uniqueness and symmetry.} We identify $\mathscr A_\omega$ with the set of $f \in L^\infty(0,\pi)$ with $0 \le f \le 1/\omega$ and $\hat f_0 = 1$, a convex set that is compact in the weak-$\ast$ topology of $L^\infty(0,\pi) = L^1(0,\pi)^\ast$. This topology is metrizable on bounded sets, $L^1(0,\pi)$ being separable. If $f_n \to f$ in it, then $\hat f_{n,k} \to \hat f_k$ for every $k$ and $\int_{\Theta_I}f_n \to \int_{\Theta_I}f$, and since $\sum_{k>K}k^{-1}\hat f_{n,k}^{\,2} \le (\pi/(2K))\lVertf_n\rVert_{L^2}^2 \le \pi^2/(2K\omega^2)$ by Bessel's inequality, Lemma~\ref{lem:cheb} gives $J_0(f_n) \to J_0(f)$. So $J_\tau$ is weak-$\ast$ continuous on the compact set $\mathscr A_\omega$ and attains its minimum. For $\lambda \ne \lambda'$ in $\mathscr A_\omega$ the bilinearity of $J_0$ gives $J_\tau(\tfrac12(\lambda + \lambda')) = \tfrac12J_\tau(\lambda) + \tfrac12J_\tau(\lambda') - \tfrac14J_0(\lambda - \lambda')$, and $J_0(\lambda - \lambda') > 0$ by Lemma~\ref{lem:cheb}; hence the minimizer $\lambda_\tau$ is unique. The reflection $\vartheta \mapsto \pi - \vartheta$ leaves $\mathscr A_\omega$, $\Theta_I$ and the kernel $\log|\cos\vartheta - \cos\varphi|$ invariant, hence $J_\tau$, and therefore fixes $\lambda_\tau$. The envelope $E := E_\tau$ is continuous by Lemma~\ref{lem:cheb}. Below $\lambda := \lambda_\tau = f\,d\theta$.

\emph{Equilibrium conditions.} For $\mu \in \mathscr A_\omega$ and $0 < \varepsilon \le 1$, the bilinearity of $J_0$ and the symmetry of the kernel give $J_\tau(\lambda + \varepsilon(\mu - \lambda)) = J_\tau(\lambda) + 2\varepsilon\int G\,d(\mu-\lambda) + \varepsilon^2J_0(\mu - \lambda)$ with $G := -E - \tau\mathbf 1_{\Theta_I}$, so the minimality of $\lambda$ forces $\int G\,d\mu \ge \int G\,d\lambda$ for all $\mu \in \mathscr A_\omega$. We claim that there is $w \in \mathbb R$ with
\begin{equation}\label{eq:bathtub}
G \le -w \ \text{ a.e.\ on } \{f > 0\}, \qquad G \ge -w \ \text{ a.e.\ on } \{f < 1/\omega\}.
\end{equation}
Both sets have positive measure, because $\hat f_0 = 1 < \pi/\omega$. If the essential supremum of $G$ on the first set exceeded the essential infimum of $G$ on the second, there would be $b < b'$ such that $A := \{f < 1/\omega,\ G < b\}$ and $B := \{f > 0,\ G > b'\}$ have positive measure, and for small $\eta > 0$ so would $A_\eta := A \cap \{f < 1/\omega - \eta\}$ and $B_\eta := B \cap \{f > \eta\}$. With $\varepsilon := \eta\min\{|A_\eta|, |B_\eta|\}$, the measure $\mu := \lambda + \varepsilon\,(\mathbf 1_{A_\eta}/|A_\eta| - \mathbf 1_{B_\eta}/|B_\eta|)\,d\theta$ lies in $\mathscr A_\omega$ and satisfies $\int G\,d\mu - \int G\,d\lambda \le \varepsilon(b - b') < 0$, a contradiction; so \eqref{eq:bathtub} holds with $-w$ the essential supremum of $G$ on $\{f > 0\}$. Conversely, if some $\lambda' = f'\,d\theta \in \mathscr A_\omega$ satisfies \eqref{eq:bathtub} with its own function $G'$ and some $w'$, then for every $\mu \in \mathscr A_\omega$ the function $(G' + w')(d\mu/d\theta - f')$ is nonnegative a.e., and $J_\tau(\mu) - J_\tau(\lambda') = 2\int(G' + w')\,d(\mu - \lambda') + J_0(\mu - \lambda') \ge 0$, so $\lambda' = \lambda_\tau$. Every point of the support of $\lambda|_{\Theta_E}$ is a limit of points of $\Theta_E \cap \{f > 0\}$ at which $G \le -w$, i.e.\ $E \ge w$, and similarly for the other three sets below; since $E$ is continuous, \eqref{eq:bathtub} gives
\begin{equation}\label{eq:pointwise}
\begin{aligned}
E &\ge w \ \text{ on } \operatorname{supp}\lambda|_{\Theta_E}, & E &\le w \ \text{ on } \operatorname{supp}(\omega^{-1}d\theta - \lambda)|_{\Theta_E}, \\
E + \tau &\ge w \ \text{ on } \operatorname{supp}\lambda|_{\Theta_I}, & E + \tau &\le w \ \text{ on } \operatorname{supp}(\omega^{-1}d\theta - \lambda)|_{\Theta_I}.
\end{aligned}
\end{equation}

\emph{Two global bounds.} Let $\lambda_0 := \pi^{-1}d\theta$, the arcsine measure, whose envelope is $-\log 2$ by Lemma~\ref{lem:cl2}(iv); it belongs to $\mathscr A_\omega$ and minimizes $J_0$ there, because $J_0(\lambda) = \hat f_0^{\,2}\log 2 + \sum_{k\ge1}(2/k)\hat f_k^{\,2} \ge \log 2 = J_0(\lambda_0)$ for $\lambda = f\,d\theta \in \mathscr A_\omega$ by Lemma~\ref{lem:cheb}. Suppose first $\lambda \ne \lambda_0$, and let $S^\pm$ be the supports of $(f - \pi^{-1})^\pm d\theta$, both nonempty since $\lambda$ and $\lambda_0$ have the same mass. Every neighbourhood of a point of $S^-$ meets $\{f < 1/\pi\} \subset \{f < 1/\omega\}$ in a set of positive measure, so the point lies in the support of $(\omega^{-1}d\theta - \lambda)|_{\Theta_E}$ or of $(\omega^{-1}d\theta - \lambda)|_{\Theta_I}$, and $E \le w$ on $S^-$ by \eqref{eq:pointwise}; likewise every point of $S^+$ lies in the support of $\lambda|_{\Theta_E}$ or of $\lambda|_{\Theta_I}$, and $E \ge w - \tau$ on $S^+$. The potentials $U^\lambda$ and $U^{\lambda_0}$ are continuous on $\mathbb C$ by Lemma~\ref{lem:env}(d), and $U^{\lambda_0} = \log 2$ on $[-1,1]$. Lemma~\ref{lem:minimum} with $(\mu_1,\mu_2,K) = (\lambda_0,\lambda,\cos S^-)$ and $u = U^\lambda - U^{\lambda_0} = -E - \log 2 \ge -w - \log 2$ on $S^-$ gives $E \le w$ on $[0,\pi]$, and with $(\mu_1,\mu_2,K) = (\lambda,\lambda_0,\cos S^+)$ and $u = U^{\lambda_0} - U^\lambda = E + \log 2 \ge w - \tau + \log 2$ on $S^+$ it gives $E \ge w - \tau$ on $[0,\pi]$. If $\lambda = \lambda_0$, then $E = -\log 2$, and \eqref{eq:pointwise}, in which all four supports are the closures of $\Theta_E$ and $\Theta_I$, forces $w = -\log 2$ and $\tau = 0$. In both cases
\begin{equation}\label{eq:two_sided}
w - \tau \le E \le w \qquad\text{on } [0,\pi].
\end{equation}
If $\lambda(\Theta_E) > 0$, then $E = w$ on the nonempty support of $\lambda|_{\Theta_E}$ by \eqref{eq:pointwise} and \eqref{eq:two_sided}, so $w = E_\tau^\ast$; then \eqref{eq:two_sided} is (i), and (ii) follows from \eqref{eq:pointwise} and (i).

\emph{Part (iv), and $\lambda_\tau(\Theta_E) > 0$ for $\tau < \kappa_\sigma$.} By Lemma~\ref{lem:clausen}, $E_{\mu_\omega}(\vartheta) = -U_\omega(\cos\vartheta)$ attains its maximum $-U_\omega(1)$ over $[0,\pi]$ at $\vartheta \in \{0,\pi\}$ and its minimum $-U_\omega(0)$ over $\Theta_I$ at $\pi/2$. For $\tau \ge \kappa_\sigma = U_\omega(0) - U_\omega(1)$ the node measure satisfies \eqref{eq:bathtub} with $w := -U_\omega(1)$: its density is $1/\omega$ on $\Theta_I$, where $G = U_\omega(\cos\vartheta) - \tau \le U_\omega(0) - \tau \le U_\omega(1)$, and $0$ on $\Theta_E$, where $G = U_\omega(\cos\vartheta) \ge U_\omega(1)$. Hence $\lambda_\tau = \mu_\omega$, and (i) and (ii) hold with $E_\tau^\ast = -U_\omega(1)$, since $E_{\mu_\omega} \ge -U_\omega(0) \ge E_\tau^\ast - \tau$ and $(\omega^{-1}d\theta - \mu_\omega)|_{\Theta_I} = 0$. Conversely, if $\lambda_\tau(\Theta_E) = 0$, then $\lambda_\tau = \mu_\omega$, the only element of $\mathscr A_\omega$ carried by $\Theta_I$, and \eqref{eq:pointwise} gives $-U_\omega(1) = \max_{\bar\Theta_E}E \le w \le \min_{\Theta_I}E + \tau = -U_\omega(0) + \tau$, that is $\tau \ge \kappa_\sigma$. So $\lambda_\tau(\Theta_E) > 0$ for $\tau < \kappa_\sigma$, which completes (i) and (ii).

\emph{The layer.} Let $\tau < \kappa_\sigma$. If $A \subset (0,\pi)$ is an open interval with $f = 1/\omega$ a.e.\ on $A$, then $\nu := \omega^{-1}d\theta - \lambda$ is a positive measure of mass $\pi/\omega - 1 > 0$ with $\nu(A) = 0$, and $E = E_{\omega^{-1}d\theta} - E_\nu = -(\pi/\omega)\log 2 - E_\nu$ by Lemma~\ref{lem:cl2}(iv); for $z$ in the open interval $\cos A$, $\frac{d^2}{dz^2}\int\log|z - \cos\varphi|\,d\nu(\varphi) = -\int(z - \cos\varphi)^{-2}\,d\nu(\varphi) < 0$, so $z \mapsto E(\arccos z)$ is strictly convex on $\cos A$. Let $O$ be the union of the relatively open subsets of $\Theta_I$ on which $f = 1/\omega$ a.e.; by the Lindel\"of property it is a countable union of such sets, so that $f = 1/\omega$ a.e.\ on $O$. Every point of $\Theta_I \setminus O$ lies in the support of $(\omega^{-1}d\theta - \lambda)|_{\Theta_I}$, where $E = E_\tau^\ast - \tau$ by (ii). A component of $O$ that contains neither $\theta_0$ nor $\pi - \theta_0$ is therefore an open interval $(\alpha,\beta)$ with $E(\alpha) = E(\beta) = E_\tau^\ast - \tau$, and strict convexity gives $E < E_\tau^\ast - \tau$ inside, contrary to (i). A component that contains both $\theta_0$ and $\pi - \theta_0$ is $\Theta_I$, which would give $\lambda = \mu_\omega$. By the symmetry of $\lambda$, $O = [\theta_0,\theta_\tau) \cup (\pi - \theta_\tau, \pi - \theta_0]$ for some $\theta_\tau \in [\theta_0,\pi/2]$, with $O = \emptyset$ if $\theta_\tau = \theta_0$, and $\theta_\tau < \pi/2$ since otherwise $f = 1/\omega$ a.e.\ on $\Theta_I$. Then $\lambda = \omega^{-1}d\theta$ on $[\theta_0,\theta_\tau]\cup[\pi-\theta_\tau,\pi-\theta_0]$, and $[\theta_\tau, \pi - \theta_\tau] \subset \Theta_I\setminus O$, where $E = E_\tau^\ast - \tau$. Moreover, $z \mapsto E(\arccos z)$ is continuous on $[\cos\theta_\tau, c_0]$ and convex inside, so $\max_{[\theta_0,\theta_\tau]}E = \max\{E(\theta_0), E(\theta_\tau)\} = E(\theta_0)$, because $E(\theta_\tau) = E_\tau^\ast - \tau \le E(\theta_0)$ by (i); by symmetry $\max_{\Theta_I}E = E(\theta_0)$. Finally, $\theta_\tau$ is unique: if $\theta' < \theta''$ both had the properties in (iii), then $f = 1/\omega$ a.e.\ and $E = E_\tau^\ast - \tau$ on $(\theta',\theta'')$, contrary to the strict convexity of $z \mapsto E(\arccos z)$ on $\cos(\theta',\theta'')$ shown above. This completes (iii).

\label{lem:construction}
Let $\mathcal C$ be a configuration. For $N \ge N_0$ let $Z_N$ be the finite multiset of points of $[0,\pi]$, counted with multiplicity, consisting of
\begin{enumerate}
    \item[(i)] the layer nodes, i.e.\ the nodes $\theta_m \in S^\ast$;
    \item[(ii)] for each arc $A_k$ with $\beta_k < \pi/2$, the lattice $\varphi^{(k)}_i := \alpha_k + (i-1)d_k$, $1 \le i \le K_k$, together with its mirror image $\pi - \varphi^{(k)}_i$, where $K_k$ is the smallest even integer with $K_k - 1 \ge \rho_k(\beta_k - \alpha_k)N$ and $d_k := (\beta_k-\alpha_k)/(K_k-1)$; for an arc with $\beta_k = \pi/2$, the lattice $\varphi^{(k)}_i := \alpha_k + (i-1)d_k$, $1 \le i \le K_k$, on $A_k^\ast = [\alpha_k, \pi-\alpha_k]$, where $K_k$ is the smallest even integer with $K_k - 1 \ge \rho_k(\pi-2\alpha_k)N$ and $d_k := (\pi - 2\alpha_k)/(K_k-1)$;
    \item[(iii)] the point $\pi/2$ if $N$ is even.
\end{enumerate}
(A point that belongs to two of these families, for instance a node at $\theta_s$ that is also the first point of a centre lattice, or the common endpoint of two adjacent arcs, is counted once for each family.) Then $Z_N$ is invariant under $\zeta \mapsto \pi - \zeta$ with multiplicities, its number of points $|Z_N|$ counted with multiplicity satisfies $|Z_N| \equiv N-1 \pmod 2$ and $|Z_N| \le N-1$, and the polynomial $P_N(z) := \prod_{\zeta\in Z_N}(z - \cos\zeta)$, the product being taken over the multiset, satisfies $P_N(-z) = (-1)^{N-1}P_N(z)$ and, with $E$ the envelope of $\mathcal C$,
\begin{enumerate}
    \item[(a)] $N^{-1}\log|P_N(\cos\vartheta)| \le E(\vartheta) + C\log N/N$ for every $\vartheta \in [0,\pi]$;
    \item[(b)] $N^{-1}\log|P_N(\cos\vartheta)| \ge E(\vartheta) - C\log N/N$ whenever $\vartheta \in [0,\pi]$ has distance at least $\Delta/4$ from every layer node, at least $d_k/4$ from every point of the $k$-th lattice for each $k$, and at least $1/N$ from $\pi/2$.
\end{enumerate}

\label{lem:correction}
Let $\chi_N^{\pm} := \ell_1^V \pm \ell_N^V \in V_N$. For $N \ge N_0$ and both signs:
\begin{enumerate}
    \item[(i)] $\chi_N^{\pm}$ vanishes at the interior nodes and $R\chi_N^{\pm} = \pm \chi_N^{\pm}$;
    \item[(ii)] $\lVert\chi_N^{\pm}\rVert_{L^\infty(I)} \le N^C$ and $\lVert\chi_N^{\pm}\rVert_{L^2(\tilde I)} \le \exp\bigl(N(\kappa_\sigma - \kappa_\Lambda) + C\log N\bigr)$;
    \item[(iii)] $p_N^{\pm} := (\tilde\mathcal{L}_P^{-1}\chi_N^{\pm})(0) = \int_{\tilde I}\tilde G(0,y)\,\chi_N^{\pm}(y)\,dy \ge \exp\bigl(N(\kappa_\sigma-\kappa_\Lambda) - C\log N\bigr)$.
\end{enumerate}
Consequently, for every $g_0 \in V_N$ with $Rg_0 = \pm g_0$, the function $g := g_0 - \alpha \chi_N^{\pm}$ with $\alpha := (\tilde\mathcal{L}_P^{-1}g_0)(0)/p_N^{\pm}$, the sign being that of $g_0$, belongs to $\Psi_N$, coincides with $g_0$ at the interior nodes, and
\begin{equation}\label{eq:alpha_bound}
|\alpha| \le C\lVertg_0\rVert_{L^2(\tilde I)}\exp\bigl(-N(\kappa_\sigma - \kappa_\Lambda) + C\log N\bigr).
\end{equation}

Fix $2 \le m \le N-1$ and put $g_0 := \ell_m^V$ and $g_0^{\pm} := \tfrac12(g_0 \pm Rg_0) = \tfrac12(\ell_m^V \pm \ell_{N+1-m}^V)$, so that $g_0 = g_0^+ + g_0^-$, $Rg_0^{\pm} = \pm g_0^{\pm}$, and $\lVertg_0^{\pm}\rVert_{L^2(\tilde I)} \le \lVertg_0\rVert_{L^2(\tilde I)}$ because $R$ is an isometry of $L^2(\tilde I)$. Lemma~\ref{lem:correction}, applied to $g_0^+$ with the sign $+$ and to $g_0^-$ with the sign $-$, gives $\alpha^{\pm}$ such that $g := g_0 - \alpha^+\chi_N^+ - \alpha^-\chi_N^- \in \Psi_N$ coincides with $g_0$ at the interior nodes, where $g_0(x_k) = \delta_{mk}$; by Assumption~\ref{ass:unisolvence}, $g = \ell_m^\Psi$. By Proposition~\ref{prop:lagrange_norms}, $\lVert\ell_m^V\rVert_{L^\infty(I)} \le \exp\bigl(N[U_\omega(z_m) - U_\omega(c_0)] + C\log N\bigr)$ and $\lVertg_0\rVert_{L^2(\tilde I)} \le \exp\bigl(N[U_\omega(z_m) - U_\omega(1)] + C\log N\bigr)$, so \eqref{eq:alpha_bound} and Lemma~\ref{lem:correction}(ii) give
\begin{align*}
|\alpha^{\pm}|\,\lVert\chi_N^{\pm}\rVert_{L^\infty(I)} &\le N^C\exp\bigl(N[U_\omega(z_m) - U_\omega(1)] - N(\kappa_\sigma - \kappa_\Lambda)\bigr) \\
&= N^C\exp\bigl(N[U_\omega(z_m) - U_\omega(c_0)]\bigr),
\end{align*}
since $\kappa_\sigma - \kappa_\Lambda = U_\omega(c_0) - U_\omega(1)$ by \eqref{eq:rates}. The triangle inequality proves (ii). For (iii), $\Lambda_N^\Psi = \max_{x\in\bar I}\sum_m|\ell_m^\Psi(x)| \le (N-2)\max_m\lVert\ell_m^\Psi\rVert_{L^\infty(I)}$, and $U_\omega(z_m) \le U_\omega(0)$ for every $m$ by Lemma~\ref{lem:clausen}, with $U_\omega(0) - U_\omega(c_0) = \kappa_\Lambda$; the bound on $\Lambda^\Psi_{N,2}$ follows from $\Lambda^\Psi_{N,2} \le \sqrt L\,\Lambda_N^\Psi$. For (iv), insert (iii) into \eqref{eq:classical}; at $t = e^{-N\kappa_\sigma}$, $e^{N\kappa_\Lambda}t = e^{-N(\kappa_\sigma-\kappa_\Lambda)} = t^{a(\omega)}$ and $e^{N\kappa_\Lambda} = t^{-\kappa_\Lambda/\kappa_\sigma} = t^{a(\omega)-1}$ by the definition $a(\omega) = 1 - \kappa_\Lambda/\kappa_\sigma$.

\label{lem:two_forms}
Let Assumption~\ref{ass:unisolvence} hold and let $b \in (0,1)$.
\begin{enumerate}
    \item[(i)] If $\gamma_t \le Ct^{\,b}$ for all $t > 0$, then $\Gamma_t \le C_bt^{\,b-1}$ for all $t > 0$, with $C_b := 2^b(1 - 4^{b-1})^{-1/2}C$.
    \item[(ii)] If $\gamma_t \le Ct^{\,b}$ and $\Gamma_t \le C't^{\,b-1}$ for all $t > 0$, then
    \[
    \lVert\Phi\mathbf{D}\mathbf{w}\rVert_{L^2(I)} \le (C + C')\lVert\mathbf{B}_D\mathbf{w}\rVert_2^{\,b}\lVert\mathbf{w}\rVert_2^{\,1-b} \qquad (\mathbf{w} \in \mathbb R^n);
    \]
    conversely this inequality with a constant $C''$ in place of $C + C'$ implies $\gamma_t \le C''t^{\,b}$ and $\Gamma_t \le C''t^{\,b-1}$ for all $t > 0$.
\end{enumerate}

\label{cor:either_or}
Let $\mathcal{L} = \mathcal{L}_P$ and let $\mathcal C$ be a configuration with $\ell := \ell(\mathcal C) > -(\kappa_\sigma - \kappa_\Lambda)$ and $\tau := \tau(\mathcal C)$. Then, with $N_0$ and $C$ as in Theorem~\ref{thm:tail_lower}, for $N \ge N_0$ and $t_N := e^{-N\tau}$,
\begin{equation}\label{eq:either_or}
\max\{\gamma_{t_N},\ t_N\Gamma_{t_N}\} \ \ge\ \tfrac12\exp\bigl(N\ell - C\log N\bigr).
\end{equation}

\label{cor:certified}
Under the hypotheses of Theorem~\ref{thm:dual} let $a := a(\omega)$, which lies in $(0,1)$, and suppose that $A_1(\mathcal S)/(1-a) \le -A_2(\mathcal S)/a$. Then for every $\tau$ with
\begin{equation}\label{eq:certified_interval}
\frac{A_1(\mathcal S)}{1-a} \le \tau \le \frac{-A_2(\mathcal S)}{a},
\end{equation}
every $N \ge N_0$ and $t = e^{-N\tau}$, one has $\gamma_t \le 2N^Ct^{\,a}$ and $\Gamma_t \le 2N^Ct^{\,a-1}$, with $N_0$ and $C$ from Theorem~\ref{thm:dual}.

\label{prop:extremal}
For $0 < \tau < \kappa_\sigma$ let
\begin{equation}\label{eq:reduced_problem}
m_\omega(\tau) := \sup\Bigl\{\max_{[-c_0,c_0]}\bigl(b - U^{\nu}\bigr)\Bigr\},
\end{equation}
the supremum being over all closed sets $F \subset [-c_0,c_0]$, constants $b \in \mathbb R$ and compactly supported positive measures $\nu$ on $\mathbb R$ with $\nu(\mathbb R) \le 1$ such that
\begin{equation}\label{eq:reduced_constraints}
b - U^\nu \le 0 \ \text{ on } [-1,1], \qquad b - U^\nu \le -\tau \ \text{ on } F, \qquad \nu \ge \mu_\omega \ \text{ on } [-c_0,c_0]\setminus F .
\end{equation}
Then $m_\omega(\tau) = r_\omega(\tau)$.

\label{lem:monotone}
Put $m_N(t) := \max\{\gamma_t,\ t\Gamma_t\}$ for $t > 0$. Then $m_N(t) > 0$, so that $r^\pm(\tau) \in [-\infty,\infty]$ are well defined for $\tau \ge 0$, and for $0 \le \tau \le \tau'$
\begin{equation}\label{eq:monotone}
r^\pm(\tau') \le r^\pm(\tau) \le r^\pm(\tau') + \tau' - \tau .
\end{equation}

Since $\Phi\mathbf{D}\mathbf{w} 
e 0$ in $L^2(I)$ for $\mathbf{w} 
e 0$ (proof of Corollary~ef{cor:either_or}), $\gamma_t > 0$ if $\mathcal V_t 
e \{0\}$, and otherwise $\mathcal V_t^\perp = \mathbb R^n$ and $t\Gamma_t > 0$. For $t > 0$ let $Q_N(t) := \sup\{\lVert\Phi\mathbf{D}\mathbf{w}Vert_{L^2(I)} : \lVert\mathbf{w}Vert_2 \le 1,\ \lVert\mathbf{B}_D\mathbf{w}Vert_2 \le t\}$. The reduction step in the proof of Theorem~ef{thm:dual} shows $m_N(t) \le Q_N(t)$, and for $\mathbf{w}$ as in the definition of $Q_N(t)$ the splitting in the proof of Corollary~ef{cor:either_or} gives $\lVert\Phi\mathbf{D}\mathbf{w}Vert_{L^2(I)} \le \gamma_t + t\Gamma_t \le 2m_N(t)$; so $Q_N(t)/2 \le m_N(t) \le Q_N(t)$. The function $Q_N$ is nondecreasing, and $Q_N(t) \ge (t/t')Q_N(t')$ for $0 < t \le t'$, because $\mathbf{w} \mapsto (t/t')\mathbf{w}$ maps the admissible set of $Q_N(t')$ into that of $Q_N(t)$. With $t = e^{-N	au'}$ and $t' = e^{-N	au}$ this gives $m_N(e^{-N	au'}) \le 2m_N(e^{-N	au})$ and $m_N(e^{-N	au'}) \ge 	frac12e^{-N(	au'-	au)}m_N(e^{-N	au})$, and \eqref{eq:monotone} follows.

\label{def:mz}
Let $\mathbf{B}$ have full column rank at the nodes $x_1,\dots,x_M$, and put
\begin{equation}\label{eq:mz}
C_M := \sup_{\psi \in \Psi_N\setminus\{0\}} \frac{\lVert\psi\rVert_{L^2(I)}}{(L/M)^{1/2}\,\bigl(\sum_{m=1}^M \psi(x_m)^2\bigr)^{1/2}} .
\end{equation}

\label{thm:regularized}
Let $\mathbf{B}$ have full column rank, let $u = \mathcal{L}^{-1}f$ and let $u_N^\varepsilon$ be defined by \eqref{eq:tsvd}. Then for every $v = \sum_{j=1}^n z_j\varphi_j \in \Phi_N$, with coefficient vector $\mathbf{z} = (z_1, \dots, z_n)^T$,
\begin{equation}\label{eq:regularized_bound}
\begin{aligned}
\lVertu - u_N^\varepsilon\rVert_{L^2(I)} \le \lVert\mathcal{L}^{-1}\rVert_{2\to 2}\Bigl[&(1 + 2C_M)\sqrt L\, \lVertf - \mathcal{L} v\rVert_{L^\infty(I)} \\
&+ C_M (L/M)^{1/2}\,\varepsilon\,\lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2\Bigr],
\end{aligned}
\end{equation}
where $\lVert\mathcal{L}^{-1}\rVert_{2\to 2}$ is the norm of $\mathcal{L}^{-1}$ on $L^2(I)$ and $\mathbf{D}^{-1}\mathbf{z}$ is the coefficient vector of $v$ in the normalized basis, $v = \Phi\mathbf{D}(\mathbf{D}^{-1}\mathbf{z})$.

\label{cor:regimes}
\leavevmode
\begin{enumerate}
    \item[(i)] Let Assumption~\ref{ass:unisolvence} hold, let $M = n$ with the interior nodes of the $N$-grid, and let $0 < \varepsilon < \sigma_n$. Then $u_N^\varepsilon = u_N$, the interpolatory solution of Theorem~\ref{thm:representation}, and
    \begin{equation}\label{eq:interp_l2}
    \lVertu - u_N\rVert_{L^2(I)} \le \lVert\mathcal{L}^{-1}\rVert_{2\to2}(1+2C_{n})\sqrt L\,\operatorname{dist}_\infty(f,\Psi_N),
    \end{equation}
    the $L^2$ analogue of \eqref{eq:error_bound}.
    \item[(ii)] Let $M \ge n$, and let the nodes be such that $\mathbf{B}$ has full column rank and $C_M \le C_\ast$ for all $N$. Then \eqref{eq:regularized_bound} holds with $C_\ast$ in place of $C_M$, uniformly in $N$, for every $\varepsilon > 0$ and every $v = \sum_{j=1}^n z_j\varphi_j \in \Phi_N$, with coefficient vector $\mathbf{z} = (z_1, \dots, z_n)^T$, and the coefficient vector $\mathbf{c}_\varepsilon$ of $u_N^\varepsilon$ in \eqref{eq:tsvd} satisfies 
\[
\lVert\mathbf{D}^{-1}\mathbf{c}_\varepsilon\rVert_2 \le \lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2 + \varepsilon^{-1}\sqrt M\,\lVertf - \mathcal{L} v\rVert_{L^\infty(I)}.
\]
\end{enumerate}

Put $\psi = \mathcal{L} v \in \Psi_N$ and $r = f - \psi$. Since $u_N^\varepsilon \in \Phi_N$, $u - u_N^\varepsilon = \mathcal{L}^{-1}(f - \mathcal{L} u_N^\varepsilon)$ and $f - \mathcal{L} u_N^\varepsilon = r + (\psi - \mathcal{L} u_N^\varepsilon)$ with $\psi - \mathcal{L} u_N^\varepsilon \in \Psi_N$. The nodal values of the latter are $\mathbf{B}\mathbf{z} - \mathbf{B}\mathbf{c}_\varepsilon = (\mathbf{B}\mathbf{z} - \mathbf{f}) + (\mathbf{f} - \mathbf{B}\mathbf{c}_\varepsilon)$, so by Lemma~\ref{lem:tsvd}
\begin{align*}
\lVert\psi - \mathcal{L} u_N^\varepsilon\rVert_{L^2(I)} &\le C_M (L/M)^{1/2}\bigl(2\lVert\mathbf{f} - \mathbf{B}\mathbf{z}\rVert_2 + \varepsilon\lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2\bigr) \\
&\le C_M\bigl(2\sqrt L\lVertr\rVert_{L^\infty(I)} + (L/M)^{1/2}\varepsilon\lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2\bigr),
\end{align*}
using $\lVert\mathbf{f} - \mathbf{B}\mathbf{z}\rVert_2 = \lVert(r(x_m))_m\rVert_2 \le \sqrt M\lVertr\rVert_\infty$. Add $\lVertr\rVert_{L^2(I)} \le \sqrt L\lVertr\rVert_\infty$ and apply $\mathcal{L}^{-1}$.

\label{thm:representation_d}
Let $\mathcal{L} = -\Delta + \mathbf k(\mathbf x)\cdot\nabla$ with $\mathbf k \in C(\bar R_0)^d$, let $f \in C(\bar R_0)$, and let $u \in C^2(R_0)\cap C(\bar R_0)$ satisfy $\mathcal{L} u = f$ in $R_0$ and $u = 0$ on $\partial R_0$. Let $\Phi_{N,d} := \{v \in V_{N,d}: v|_{\partial R_0} = 0\}$ and $\Psi_{N,d} := \mathcal{L}(\Phi_{N,d})$, and suppose that interpolation at the interior nodes is unisolvent in $\Psi_{N,d}$, with interpolation operator $\mathcal{P}_{N,d}$ and Lebesgue constant $\Lambda(\Psi_{N,d})$. Then the interpolatory solution $u_N \in V_{N,d}$ with homogeneous Dirichlet data at the boundary nodes is the unique function in $C^2(R_0)\cap C(\bar R_0)$ with $\mathcal{L} u_N = \mathcal{P}_{N,d}f$ in $R_0$ and $u_N = 0$ on $\partial R_0$, and with $\alpha := \max_{\bar R_0}|k_1| + 1$,
\begin{equation}\label{eq:error_bound_d}
\begin{aligned}
\lVertu - u_N\rVert_{L^\infty(R_0)} &\le (e^{\alpha L_1} - 1)\bigl(1 + \Lambda(\Psi_{N,d})\bigr)\operatorname{dist}_\infty(f, \Psi_{N,d}), \\
\sum_m|(\mathbf{G}_N)_{im}| &\le (e^{\alpha L_1} - 1)\Lambda(\Psi_{N,d}),
\end{aligned}
\end{equation}
where $\mathbf{G}_N = \mathbf{W}_d\mathbf{A}^{-1}$ maps nodal data to nodal values, $\mathbf x_i$ is any interior node and the sum runs over the interior nodes $\mathbf x_m$. If moreover $\mathbf k$ is constant and $u \in C^2(\bar R_0)$, then Theorem~\ref{thm:regularized} holds with $R_0$ in place of $I$, the products $\varphi_{j_1}(x_1)\cdots\varphi_{j_d}(x_d)$ of the one-dimensional bases of Section~\ref{sec:constants} in place of the $\varphi_j$, $|R_0|$ in place of $L$ in the definition \eqref{eq:mz} of $C_M$ and in \eqref{eq:regularized_bound}, and $\lVert\mathcal{L}^{-1}\rVert_{2\to2}$ replaced by $(\sum_i\pi^2/L_i^2)^{-1}$.

\label{cor:certified_instances}
Let the nodes be the interior nodes of the $N$-grid ($M = n$), and let $\mathcal{L} = \mathcal{L}_P$.
\begin{enumerate}
    \item[(i)] For $\delta = L/4$ the configuration $\mathcal C$ of Table~\ref{tab:config_quarter} satisfies $\ell(\mathcal C) + a(\omega)\tau(\mathcal C) \ge 0.0084$, so there are no $N_1$ and $C$ with $\gamma_t \le Ct^{\,a(\omega)}$ for all $N \ge N_1$ and all $t > 0$; in particular the sharp power law \eqref{eq:sharp_law} fails.
    \item[(ii)] There are $N_0$ and $C$, depending only on $L$, such that for all $N \ge N_0$ and $t = e^{-N\tau}$: for $\delta = L$ ($\omega = \pi/3$, $a = 3/5$) and every $\tau \in [0.097, 0.913]\,\kappa_\sigma(\pi/3)$, $\gamma_t \le 2N^Ct^{\,3/5}$ and $\Gamma_t \le 2N^Ct^{-2/5}$; for $\delta = 2L$ ($\omega = \pi/5$) and every $\tau \in [0.080, 0.960]\,\kappa_\sigma(\pi/5)$, $\gamma_t \le 2N^Ct^{\,a(\pi/5)}$ and $\Gamma_t \le 2N^Ct^{\,a(\pi/5)-1}$.
\end{enumerate}

\label{lem:dirichlet_1d}
Let $k \in C(\bar I)$, $K(x) := \int_0^x k(s)\,ds$, $E(x) := \int_0^x e^{K(s)}\,ds$, and
\begin{equation}\label{eq:green_general}
G(x,y) := \frac{e^{-K(y)}\,E(\min\{x,y\})\,\bigl(E(L) - E(\max\{x,y\})\bigr)}{E(L)}, \qquad x, y \in \bar I .
\end{equation}
\begin{enumerate}
\item[(i)] (Maximum principle.) If $v \in C^2(I)\cap C(\bar I)$ and $\mathcal{L} v \le 0$ on $I$, then $\max_{\bar I} v = \max\{v(0), v(L)\}$. Consequently, if $\mathcal{L} v = 0$ on $I$ then $\min\{v(0),v(L)\} \le v \le \max\{v(0),v(L)\}$ on $\bar I$, and if in addition $v(0) = v(L) = 0$ then $v \equiv 0$.
\item[(ii)] (Solution formula.) For $g \in C(\bar I)$ the function $v := \int_0^L G(\cdot,y)\,g(y)\,dy$ belongs to $C^2(\bar I)$ and is the unique element of $C^2(I)\cap C(\bar I)$ with $\mathcal{L} v = g$ on $I$ and $v(0) = v(L) = 0$. We write $v = \mathcal{L}^{-1}g$.
\item[(iii)] $G \ge 0$ is continuous on $\bar I\times\bar I$,
\[
\lVert\mathcal{L}^{-1}\rVert_\infty = \sup_{g\ne0}\frac{\lVert\mathcal{L}^{-1}g\rVert_{L^\infty(I)}}{\lVertg\rVert_{L^\infty(I)}} = \max_{x\in\bar I}\int_0^L G(x,y)\,dy = \max_{\bar I}\bigl(\mathcal{L}^{-1}\mathbf 1\bigr),
\]
and the norm $\lVert\mathcal{L}^{-1}\rVert_{2\to2}$ of $\mathcal{L}^{-1}$ on $L^2(I)$ is at most $\lVertG\rVert_{L^2(I\times I)}$.
\end{enumerate}

\label{prop:continuous_greens}
On $I=(0,L)$ with homogeneous Dirichlet conditions,
\begin{align}
G_P(x,y) &= \begin{cases} x(L-y)/L, & x \le y, \\ y(L-x)/L, & x > y, \end{cases} & \lVert\mathcal{L}_P^{-1}\rVert_\infty &= \frac{L^2}{8}, \label{eq:GP}\\
G_{CD}(x,y) &= \begin{cases} a(y)\,(e^{kx}-1), & x \le y, \\ b(y)\,(e^{kx} - e^{kL}), & x > y, \end{cases}
& \lVert\mathcal{L}_{CD}^{-1}\rVert_\infty &\le \frac{L}{k}\quad (k>0), \label{eq:GCD}
\end{align}
with $b(y) = -(1-e^{-ky})/\bigl(k(e^{kL}-1)\bigr)$ and $a(y) = b(y) + e^{-ky}/k$. For $k>0$ and $x \le y$, $0 \le G_{CD}(x,y) \le k^{-1} e^{-k(y-x)}$, whereas for $x > y$, $G_{CD}(x,y) = k^{-1}(1-e^{-ky})(1 - e^{-k(L-x)})/(1 - e^{-kL})$.

\label{lem:dirichlet_box}
Let $U \subset \mathbb R^d$ be a bounded open set contained in the slab $\{0 \le x_1 \le \ell\}$, let $\mathcal{L} = -\Delta + \mathbf k\cdot\nabla$ with a bounded function $\mathbf k: U \to \mathbb R^d$, and put $\alpha := \sup_U|k_1| + 1$.
\begin{enumerate}
\item[(i)] If $v \in C^2(U)\cap C(\bar U)$ and $\mathcal{L} v \le 0$ in $U$, then $\max_{\bar U}v = \max_{\partial U}v$.
\item[(ii)] If $v \in C^2(U)\cap C(\bar U)$, $\mathcal{L} v = g$ in $U$ with $g$ bounded, and $v = 0$ on $\partial U$, then $\sup_U|v| \le (e^{\alpha\ell} - 1)\sup_U|g|$. In particular the Dirichlet problem for $\mathcal{L}$ has at most one solution in $C^2(U)\cap C(\bar U)$.
\item[(iii)] If $U = R_0 = \prod_{i=1}^d(0,L_i)$, $\mathbf k$ is constant, $v \in C^2(\bar R_0)$, $\mathcal{L} v = g$ and $v = 0$ on $\partial R_0$, then $\lVertv\rVert_{L^2(R_0)} \le \bigl(\sum_{i=1}^d\pi^2/L_i^2\bigr)^{-1}\lVertg\rVert_{L^2(R_0)}$.
\end{enumerate}

\label{lem:cl2}
The Clausen function $\mathrm{Cl}_2$ of Section~\ref{sec:variable} is odd and $2\pi$-periodic, and:
\begin{enumerate}
\item[(i)] $\mathrm{Cl}_2(\pi) = 0$ and $\mathrm{Cl}_2(2\pi - x) = -\mathrm{Cl}_2(x)$;
\item[(ii)] $\mathrm{Cl}_2(2x) = 2\mathrm{Cl}_2(x) - 2\mathrm{Cl}_2(\pi - x)$ for all $x$; in particular $\mathrm{Cl}_2(\pi/3) = \tfrac32\mathrm{Cl}_2(2\pi/3)$;
\item[(iii)] $\mathrm{Cl}_2(x) = x(1 - \log x) + O(x^3)$ and $\mathrm{Cl}_2(\pi - x) = x\log 2 + O(x^3)$ as $x \to 0^+$;
\item[(iv)] $\int_0^\pi\log|\cos\theta - \cos\varphi|\,d\varphi = -\pi\log 2$ for every $\theta \in [0,\pi]$.
\end{enumerate}

\label{lem:tsvd}
Let $M \ge n$, $\varepsilon > 0$ and $\mathbf{c}_\varepsilon$ be as in \eqref{eq:tsvd}. For every $\mathbf{z} \in \mathbb R^{n}$,
\begin{equation}\label{eq:tsvd_ineq}
\lVert\mathbf{f} - \mathbf{B}\mathbf{c}_\varepsilon\rVert_2 \le \lVert\mathbf{f} - \mathbf{B}\mathbf{z}\rVert_2 + \varepsilon\,\lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2, \qquad
\lVert\mathbf{D}^{-1}\mathbf{c}_\varepsilon\rVert_2 \le \lVert\mathbf{D}^{-1}\mathbf{z}\rVert_2 + \varepsilon^{-1}\lVert\mathbf{f} - \mathbf{B}\mathbf{z}\rVert_2 .
\end{equation}

\label{lem:riemann}
For $\vartheta \in [0,\pi]$ put $g_\vartheta(\varphi) := \log|\cos\vartheta - \cos\varphi|$. Then for all $N \ge N_0$ and all $\vartheta \in [0,\pi]$:
\begin{enumerate}
    \item[(a)] if $|\vartheta - \theta_m| \ge \Delta/4$ for every $m$, then
    $\bigl|\Delta\sum_{m=1}^N g_\vartheta(\theta_m) - \int_{\theta_0}^{\pi-\theta_0} g_\vartheta(\varphi)\,d\varphi\bigr| \le C\,\Delta\log(1/\Delta)$;
    \item[(b)] if $|\vartheta - \theta_j| < \Delta/4$ for some $j$, then the same bound holds for the sum with the term $m = j$ omitted.
\end{enumerate}

\label{lem:discrete_potential}
For $N \ge N_0$, with $z = \cos\vartheta$, $\vartheta \in [0,\pi]$:
\begin{enumerate}
    \item[(a)] if $|\vartheta - \theta_m| \ge \Delta/4$ for every $m$, then $|U_N(z) - U_\omega(z)| \le C\log N/N$;
    \item[(b)] if $|\vartheta - \theta_j| < \Delta/4$ for some $j$, then $|U_N^{(j)}(z) - U_\omega(z)| \le C\log N/N$; in particular $N^{-1}\log|\omega_N'(z_j)| = -U_\omega(z_j) + O(\log N/N)$ uniformly in $j$.
\end{enumerate}

\label{lem:lagrange_polynomials}
Let $\ell_m(z) := \omega_N(z)/\bigl((z-z_m)\,\omega_N'(z_m)\bigr)$, $1 \le m \le N$, be the Lagrange polynomials of the nodes $z_1,\dots,z_N$. For $N \ge N_0$ and $z = \cos\vartheta$:
\begin{enumerate}
    \item[(a)] for all $\vartheta \in [0,\pi]$ and all $m$, $N^{-1}\log|\ell_m(z)| \le U_\omega(z_m) - U_\omega(z) + C\log N/N$;
    \item[(b)] if $|\vartheta - \theta_k| \ge \Delta/4$ for every $k$, then for all $m$, $N^{-1}\log|\ell_m(z)| \ge U_\omega(z_m) - U_\omega(z) - C\log N/N$.
\end{enumerate}

Since $\omega_N(z)/(z - z_m) = \prod_{k\ne m}(z - z_k)$ and $\omega_N'(z_m) = \prod_{k\ne m}(z_m - z_k)$, one has $\ell_m(z_k) = \delta_{mk}$, and for $z \notin \{z_1, \dots, z_N\}$
\begin{equation}\label{eq:log_lagrange}
\begin{aligned}
\log|\ell_m(z)| &= \log|\omega_N(z)| - \log|z - z_m| - \log|\omega_N'(z_m)| \\
&= -NU_N(z) - \log|z - z_m| + NU_N^{(m)}(z_m),
\end{aligned}
\end{equation}
where $NU_N^{(m)}(z_m) = -\log|\omega_N'(z_m)| = NU_\omega(z_m) + O(\log N)$ uniformly in $m$ by Lemma~\ref{lem:discrete_potential}(b). If $z = z_k$ for some $k \ne m$, then $\ell_m(z) = 0$ and (a) holds trivially; this can only occur in Case~2 below.

\emph{Case 1: $|\vartheta - \theta_k| \ge \Delta/4$ for every $k$.} Then $-NU_N(z) = -NU_\omega(z) + O(\log N)$ by Lemma~\ref{lem:discrete_potential}(a). Moreover $|z - z_m| \le 2$, and by the two elementary facts of this appendix, applied with $|\vartheta - \theta_m| \le \pi$ and $\theta_m \in [\theta_0, \pi-\theta_0]$,
\begin{equation}\label{eq:node_distance}
|z - z_m| = 2\,\bigl|\sin\tfrac12(\vartheta-\theta_m)\bigr|\,\sin\tfrac12(\vartheta+\theta_m) \ge 2\cdot\frac{|\vartheta - \theta_m|}{\pi}\cdot\sin\frac{\theta_0}{4} \ge \frac{\Delta}{2\pi}\sin\frac{\theta_0}{4},
\end{equation}
so $|\log|z - z_m|| \le C\log N$. Inserting the three estimates into \eqref{eq:log_lagrange} gives $\log|\ell_m(z)| = N[U_\omega(z_m) - U_\omega(z)] + O(\log N)$, which proves (b) and the case of (a) in which $\vartheta$ is at distance at least $\Delta/4$ from every node.

\emph{Case 2: $|\vartheta - \theta_j| < \Delta/4$ for some $j$}, necessarily unique. If $j = m$, write $\log|\ell_m(z)| = \sum_{k\ne m}\bigl(\log|z - z_k| - \log|z_m - z_k|\bigr) = N\bigl[U_N^{(m)}(z_m) - U_N^{(m)}(z)\bigr]$ and apply Lemma~\ref{lem:discrete_potential}(b) at $z$ and at $z_m$: $\log|\ell_m(z)| = N[U_\omega(z_m) - U_\omega(z)] + O(\log N)$. If $j \ne m$, then $|\vartheta - \theta_m| \ge |\theta_j - \theta_m| - |\vartheta - \theta_j| \ge 3\Delta/4$, so \eqref{eq:node_distance} holds and gives $-\log|z - z_m| \le C\log N$; and $\log|\omega_N(z)| = \log|z - z_j| - NU_N^{(j)}(z) \le \log 2 - NU_\omega(z) + C\log N$ by Lemma~\ref{lem:discrete_potential}(b). Inserting into \eqref{eq:log_lagrange} gives $\log|\ell_m(z)| \le N[U_\omega(z_m) - U_\omega(z)] + C\log N$. This completes the proof of (a).

\label{lem:U_modulus}
For all $\vartheta, \vartheta' \in [0,\pi]$ with $|\vartheta - \vartheta'| \le 1/2$,
\begin{equation}\label{eq:U_modulus}
|U_\omega(\cos\vartheta) - U_\omega(\cos\vartheta')| \le C|\vartheta - \vartheta'|\bigl(1 + \log(1/|\vartheta-\vartheta'|)\bigr).
\end{equation}

\label{lem:nodal_sines}
There are $c_S > 0$ and $N_0$, depending only on $\theta_0$, such that for all $N \ge N_0$, all integers $3 \le J \le N$ and all $\beta \in \mathbb R$,
\begin{equation}\label{eq:nodal_sines}
\sum_{m=2}^{N-1}\sin^2(J\theta_m + \beta) \ge c_S\,N .
\end{equation}

\label{lem:column_norms}
There are $0 < c_B \le C_B$ and $N_0$, depending only on $\theta_0$, $L$ and $k$, such that for all $N \ge N_0$ and $1 \le j \le n$,
\begin{equation}\label{eq:column_norms}
c_B\,\rho_{j+2}\sqrt N \le \lVert\mathbf{B}\mathbf{e}_j\rVert_2 \le C_B\,\rho_{j+2}\sqrt N .
\end{equation}

\label{lem:riemann_arc}
Let $0 < \xi < \pi/2$, $[\alpha,\beta] \subset [\xi, \pi-\xi]$, $K \ge 2$, $d := (\beta-\alpha)/(K-1) \le \min\{\xi, 1\}/4$, and $\varphi_i := \alpha + (i-1)d$ for $1 \le i \le K$. With $g_\vartheta(\varphi) = \log|\cos\vartheta - \cos\varphi|$ as in Lemma~\ref{lem:riemann}, there is a constant $C_\xi$ depending only on $\xi$ such that for all $\vartheta \in [0,\pi]$:
\begin{enumerate}
    \item[(a)] if $|\vartheta - \varphi_i| \ge d/4$ for every $i$, then $\bigl|d\sum_{i=1}^K g_\vartheta(\varphi_i) - \int_\alpha^\beta g_\vartheta\bigr| \le C_\xi\,d\log(1/d)$;
    \item[(b)] if $|\vartheta - \varphi_j| < d/4$ for some $j$, then the same bound holds for the sum without the term $i = j$.
\end{enumerate}

\label{lem:E_modulus}
For $0 \le \alpha < \beta \le \pi$ the function $F(\vartheta) := \int_\alpha^\beta\log|\cos\vartheta - \cos\varphi|\,d\varphi$ is absolutely continuous on $[0,\pi]$, with
\begin{equation}\label{eq:arc_derivative}
F'(\vartheta) = \log\frac{\bigl|\sin\tfrac12(\vartheta+\beta)\,\sin\tfrac12(\vartheta-\alpha)\bigr|}{\bigl|\sin\tfrac12(\vartheta+\alpha)\,\sin\tfrac12(\vartheta-\beta)\bigr|} \qquad (\vartheta \notin\{\alpha,\beta\}),
\end{equation}
and $|F(\vartheta) - F(\vartheta')| \le 4s\bigl(1 + \log(2\pi/s)\bigr)$ for $s := |\vartheta - \vartheta'| \le 1/2$. Consequently the envelope of a configuration satisfies
\begin{equation}\label{eq:E_modulus}
|E(\vartheta) - E(\vartheta')| \le M(\mathcal C)\,s\bigl(1 + \log(2\pi/s)\bigr), \qquad M(\mathcal C) := 4\Bigl(\frac2\omega + \sum_{k=1}^Q n_k\rho_k\Bigr),
\end{equation}
where $n_k = 2$ if $\beta_k < \pi/2$ and $n_k = 1$ if $\beta_k = \pi/2$ is the number of arcs in $A_k^\ast$.

\label{lem:env}
Let $h(t) = \log|2\sin(t/2)|$ as in \eqref{eq:kernel_split} and $\Omega(s) := \sup_{0\le s'\le s}\int_{-\pi}^{\pi}|h(t+s') - h(t)|\,dt$ for $s > 0$. Then $\Omega(s) \le 4s(1 + \log(\pi/s))$ for $0 < s \le 1$, and for $f, g \in L^\infty(0,\pi)$ with $|f| \le M$ and $|g| \le M$:
\begin{enumerate}
    \item[(a)] $|E_f(\vartheta) - E_f(\vartheta')| \le M\,\Omega(|\vartheta - \vartheta'|)$ for $\vartheta, \vartheta' \in [0,\pi]$;
    \item[(b)] $\int_B\bigl|\log|\cos\vartheta - \cos\varphi|\bigr|\,d\varphi \le C_0|B|^{1/2}$ for every $\vartheta \in [0,\pi]$ and every Borel set $B \subset [0,\pi]$, with $C_0 := \sqrt\pi\,(\log 2 + \pi/\sqrt3)$; in particular $|E_f| \le MC_0|B|^{1/2}$ on $[0,\pi]$ if $f$ vanishes outside $B$;
    \item[(c)] if $[0,\pi]$ is the union of arcs $A_1,\dots,A_q$ with pairwise disjoint interiors and lengths in $[\eta/2,\eta]$, $0 < \eta \le 1$, and $\int_{A_j}f = \int_{A_j}g$ for every $j$, then $|E_f - E_g| \le 8M\,\Omega(\eta)$ on $[0,\pi]$;
    \item[(d)] if $f \ge 0$, the potential $U^{f\,d\theta}$ is continuous on $\mathbb C$.
\end{enumerate}

\label{lem:lattice_lagrange}
Let $\mathcal S$ be an interpolation configuration with envelope $E$, and put $X := 1 + 3\sum_{k\le Q_1}|R_k|$. For $N \ge N_0$ let $S_N \subset [\xi,\pi-\xi]$ consist of
\begin{enumerate}
    \item[(i)] for each node arc $A_k$, the interior nodes $\theta_m \in A_k$, $2 \le m \le N-1$, with $m \equiv r \pmod{q_k}$ for some $r \in R_k$;
    \item[(ii)] for each virtual arc $A_k$, the lattice $\varphi_i^{(k)} := \alpha_k + (i-1)d_k$, $1 \le i \le K_k$, with $K_k := \lceil\rho_k(\beta_k - \alpha_k)N\rceil + X$ and $d_k := (\beta_k - \alpha_k)/(K_k - 1)$.
\end{enumerate}
Then the points of $S_N$ are distinct, their number $N'$ satisfies $N \le N' \le N + K_0$ with $K_0$ depending only on $\mathcal S$, and the Lagrange polynomials $\ell_s(z) := \omega_S(z)/\bigl((z - \cos s)\,\omega_S'(\cos s)\bigr)$ of the set $\{\cos s : s \in S_N\}$, where $\omega_S(z) := \prod_{s\in S_N}(z - \cos s)$, satisfy, for all $s \in S_N$ and all $\vartheta \in [0,\pi]$,
\begin{equation}\label{eq:lattice_lagrange}
N^{-1}\log|\ell_s(\cos\vartheta)| \le E(\vartheta) - E(s) + C\,\frac{\log N}{N},
\end{equation}
with $C$ and $N_0$ depending only on $\mathcal S$.

\emph{Lattices and counting.} For a node arc $A_k$ and a residue $r \in R_k$, the nodes of (i) with $m \equiv r$ form a lattice of spacing $q_k\Delta$ whose points lie in $A_k$, since the nodes are the points $\theta_0 + \Delta\mathbb Z$ in $[\theta_0,\pi-\theta_0]$; it has between $(\beta_k - \alpha_k)/(q_k\Delta) - 3$ and $(\beta_k - \alpha_k)/(q_k\Delta) + 1$ points, because an interval of length $\ell$ contains between $\ell/(q_k\Delta) - 1$ and $\ell/(q_k\Delta) + 1$ points of a lattice of spacing $q_k\Delta$ and at most two of them, $\theta_1$ and $\theta_N$, are excluded as boundary nodes. With $1/\Delta = (N-1)/\omega$ and $\rho_k = |R_k|/(q_k\omega)$, the node arcs contribute between $(N-1)m_1 - 3\sum_{k\le Q_1}|R_k|$ and $(N-1)m_1 + \sum_{k\le Q_1}|R_k|$ points, where $m_1 := \sum_{k\le Q_1}\rho_k(\beta_k-\alpha_k) \le 1$; the virtual arcs contribute between $Nm_2 + Q_2X$ and $Nm_2 + Q_2(X+1)$ points, where $m_2 := \sum_{k>Q_1}\rho_k(\beta_k-\alpha_k)$ and $Q_2 \ge 1$ is their number. Since $m_1 + m_2 = 1$, $N' \ge N - 1 - 3\sum_{k\le Q_1}|R_k| + Q_2X \ge N$ by the choice of $X$, and $N' \le N + K_0$ with $K_0 := \sum_{k\le Q_1}|R_k| + Q_2(X+1)$. The points are distinct: two residue lattices of the same node arc consist of nodes with different residues, points of different arcs lie in disjoint arcs, and the points of a lattice are distinct. Thus $S_N$ is the union of $P := \sum_{k\le Q_1}|R_k| + Q_2$ lattices $\Lambda_1, \dots, \Lambda_P$; the $j$-th of them has spacing $d_j$, $K_j \ge 2$ points, lies on an arc $[a_j,b_j] \subset [\xi,\pi-\xi]$ with $b_j - a_j = (K_j - 1)d_j$, and has density $\varrho_j$ ($= 1/(q_k\omega)$ for a residue lattice of the node arc $A_k$, $= \rho_k$ for a virtual arc) in the sense that $d_j^{-1} = \varrho_jN + O(1)$: for a residue lattice $d_j^{-1} = (N-1)/(q_k\omega)$, and for a virtual arc $d_j^{-1} = (K_k-1)/(\beta_k - \alpha_k) \in [\rho_kN + (X-1)/(\beta_k-\alpha_k),\ \rho_kN + X/(\beta_k-\alpha_k))$. For $N \ge N_0$ every spacing is at most $\min\{\xi,1\}/4$ and every $K_j \ge 2$. The arc $[a_j,b_j]$ of a virtual lattice is $A_k$; that of a residue lattice lies in $A_k$ and differs from it by two intervals of length less than $(q_k+1)\Delta$ each, which is at most $C/N$ and, for $N \ge N_0$, at most $1/4$.

\emph{Products.} For $\vartheta \in [0,\pi]$, $\log|\omega_S(\cos\vartheta)| = \sum_{j=1}^P\sum_{i=1}^{K_j}g_\vartheta(\varphi_i^{(j)})$ with $g_\vartheta(\varphi) = \log|\cos\vartheta - \cos\varphi|$ as in Lemma~\ref{lem:riemann}. For each lattice, Lemma~\ref{lem:riemann_arc} with $d = d_j$ gives $d_j\sum_ig_\vartheta(\varphi^{(j)}_i) = \int_{a_j}^{b_j}g_\vartheta + O(d_j\log(1/d_j))$, the sum being taken without the point of the lattice within $d_j/4$ of $\vartheta$ if there is one (there is at most one, the points being $d_j$ apart). Dividing by $d_j$ and using $d_j^{-1} = \varrho_jN + O(1)$, $\log(1/d_j) \le C\log N$, $|\int_{a_j}^{b_j}g_\vartheta| \le \int_0^\pi|g_\vartheta| \le C$ and, for the residue lattices, $|\int_{A_k}g_\vartheta - \int_{a_j}^{b_j}g_\vartheta| \le C\log N/N$ (the integral of $|g_\vartheta|$ over an interval of length $\lambda \le 1/4$ inside $[\xi/2,\pi-\xi/2]$ is at most $C\lambda(1 + \log(1/\lambda))$, by the bound on the end half-cells in the proof of Lemma~\ref{lem:riemann}), we obtain for the sum $\Sigma^\circ_\vartheta$ over $S_N$ without the points within a quarter spacing of $\vartheta$
\begin{equation}\label{eq:lattice_sum}
\Sigma^\circ_\vartheta = N\sum_{k=1}^Q\rho_k\int_{A_k}g_\vartheta + O(\log N) = NE(\vartheta) + O(\log N),
\end{equation}
since the residue lattices of $A_k$ together have density $|R_k|/(q_k\omega) = \rho_k$. Each omitted point contributes a factor of modulus at most $2$, so
\begin{equation}\label{eq:lattice_upper}
\log|\omega_S(\cos\vartheta)| \le NE(\vartheta) + C\log N \qquad\text{for all } \vartheta \in [0,\pi].
\end{equation}

\emph{Derivatives.} Let $s \in S_N$. Then $\log|\omega_S'(\cos s)| = \sum_{s' \in S_N\setminus\{s\}}g_s(s')$. In the lattice of $s$ no other point lies within a quarter spacing of $s$, and in every other lattice at most one point $s'$ does; such a point is at distance at least $\Delta$ from $s$ if both are nodes and at least the distance between their arcs otherwise, so $|s - s'| \ge c/N$ with $c > 0$ depending on $\mathcal S$, and since $s, s' \in [\xi,\pi-\xi]$,
\begin{equation}\label{eq:point_distance}
|\cos s - \cos s'| = 2\bigl|\sin\tfrac12(s-s')\bigr|\sin\tfrac12(s+s') \ge \frac{2\sin\xi}{\pi}\,|s - s'| \ge \frac{c'}{N},
\end{equation}
by the first elementary fact of Appendix~\ref{app:rates} and $\tfrac12(s+s') \in [\xi,\pi-\xi]$. Hence $g_s(s') \ge -C\log N$ for the at most $P$ omitted points, and \eqref{eq:lattice_sum} with $\vartheta = s$ gives
\begin{equation}\label{eq:lattice_lower}
\log|\omega_S'(\cos s)| \ge NE(s) - C\log N .
\end{equation}

\emph{Lagrange polynomials.} Let $s \in S_N$, $d_s$ the spacing of its lattice, and $\vartheta \in [0,\pi]$. If $|\vartheta - s| \ge d_s/4$, then $|\cos\vartheta - \cos s| \ge (2\sin(\xi/4)/\pi)|\vartheta - s| \ge c/N$ by the two elementary facts of Appendix~\ref{app:rates} with $\xi$ in place of $\theta_0$ (as $s \in [\xi,\pi-\xi]$), and \eqref{eq:lattice_upper}, \eqref{eq:lattice_lower} give $\log|\ell_s(\cos\vartheta)| = \log|\omega_S(\cos\vartheta)| - \log|\cos\vartheta - \cos s| - \log|\omega_S'(\cos s)| \le N[E(\vartheta) - E(s)] + C\log N$. If $|\vartheta - s| < d_s/4$, write $\log|\ell_s(\cos\vartheta)| = \sum_{s'\ne s}g_\vartheta(s') - \sum_{s'\ne s}g_s(s')$; the second sum is at least $NE(s) - C\log N$ by \eqref{eq:lattice_lower}, and the first is at most $NE(\vartheta) + C\log N$ by the argument of \eqref{eq:lattice_upper}, in which the point of the lattice of $s$ within a quarter spacing of $\vartheta$ is $s$ itself. This proves \eqref{eq:lattice_lagrange}.

\label{lem:inner}
\leavevmode
\begin{enumerate}
    \item[(i)] The function $e$ is absolutely continuous and nonincreasing, with $e(0) = -2\theta_0/\pi$. Its derivative is $e'(x) = -\omega^{-1}\log|(t(x) + s_0)/(t(x) - s_0)|$ on $(-g,l)\setminus\{0\}$ and $e' = 0$ on $\mathbb R\setminus(-g,l)$; it is H\"older continuous with exponent $1/2$ on every compact subset of $\mathbb R\setminus\{0\}$, $e' \in L^p(\mathbb R)$ for $1 \le p < \infty$, and $\int_{\mathbb R}|e'| = 1$.
    \item[(ii)] For every $x \ne 0$ the principal value $\pi^{-1}\,\mathrm{p.v.}\!\int_{\mathbb R}e'(y)\,(x-y)^{-1}\,dy$ exists and equals $1 - \pi m(x)$.
    \item[(iii)] The function $m$ is continuous on $\mathbb R\setminus\{0\}$, $0 \le m \le 1/\omega$, $m > 1/\pi$ on $(l,\infty)$, and $m(x) \to 1/\pi$ as $x \to -\infty$.
\end{enumerate}

\label{lem:shape}
Let $q$ be an absolutely continuous function on $[0,\pi]$ with $q' \in L^2(0,\pi)$ and cosine coefficients $\hat q_k := \int_0^\pi q(\varphi)\cos k\varphi\,d\varphi$, and let $\mathcal Nq \in L^2(0,\pi)$ be the function with the cosine series $(2/\pi)\sum_{k\ge1}k\,\hat q_k\cos k\vartheta$.
\begin{enumerate}
    \item[(i)] For $\tau \ge 0$ the function $f := \pi^{-1}(1 - \tau\mathcal Nq)$ satisfies $\int_0^\pi f = 1$ and $E_f = -\log 2 + \tau(q - \pi^{-1}\hat q_0)$ on $[0,\pi]$.
    \item[(ii)] If $q'$ is H\"older continuous on a neighbourhood of $\vartheta \in (0,\pi)$, the principal value
    \[
    P(\vartheta) := \frac1\pi\,\mathrm{p.v.}\!\int_0^\pi q'(\varphi)\,\frac{\sin\varphi}{\cos\varphi - \cos\vartheta}\,d\varphi
    \]
    exists. If this holds for all $\vartheta \in (0,\pi)$ outside a finite set, then $\mathcal Nq = P$ a.e.
\end{enumerate}
